SY_TALK("hKIdmBrZjeQ.hi",[[7,["बैठिए, बैठिए।"]],[47,["ज़रा इनसे कहना डिस्टर्ब नहीं करो नहीं तो कुछ","देना हो वो भी नहीं देंगे, कहना। भीख माँगने","की प्रथा है।"]],[56,["हाँ! मैं सुन रही थी कुछ आप लोगों के प्रश्न और","कुछ उसके उत्तर भी, जिस पर कि ये वाद-विवाद","हो रहा है"]],[72,["के, माँ को ही ये क्यों कार्य करना","पड़ता है? तो ये प्रश्न दो तरह से"]],[85,["ये प्रश्न जो है ये दो कारण से पूछा जा सकता है।"]],[91,["एक तो ये कि, \"क्यों हमारी माँ को इतनी तकलीफ","उठानी पड़ती है, बाप को सब काम करना चाहिए,\""]],[96,["और दूसरा ये कि, \"हम तो बाप ही को मानते हैं,","तो माँ को ये काम करना चाहिए।\""]],[102,["अब विधाता की बात ऐसी है कि जो काम जो कर","सकता है उसी के हवाले वो वो काम करते हैं,","क्योंकि समझदार हैं।"]],[113,["कुण्डलिनी जागरण का काम करना कोई","आसान चीज़ नहीं है,"]],[118,["खासकर कलयुग में जबकि घोर कलयुग छाया है","और आसुरी विद्या फैली हुई है।"]],[124,["इस वकत लोग ऐसे भी हैं जो महापाप कर बैठे हैं","- अनंत पाप किये हुए हैं उन्होंने अपने जीवन","में, इस जीवन मैं।"]],[133,["और ऐसे लोग हैं जिन्होंने अपनी कुण्डलिनी","को भी हताहत कर दिया है।"]],[138,["आपको समझाने के लिए तो मैं कह रही थी कल","कि ऐसे नहीं सोचिए कि, \"मेरे कोई दोष नहीं है,"]],[144,["मेरे में अंदर कोई तकलीफ नहीं है,\" - इसी तरह","से सोचिए पहले, जिससे कि आपका आत्मविश्वास","बन जाए।"]],[151,["लेकिन आपको जानना चाहिए कि आज कलयुग","जुग में हम लोग अधोगति की तरफ इतने ज़्यादा","कीचड में धस गए हैं,"]],[159,["कि उसमें निकालने का काम एक माँ ही कर","सकती है जिसके अंदर ह्रदय में प्रेम हो","और शक्ति हो।"]],[166,["इतना ही नहीं पर आखिर तक ये काम निभाने","की प्रेममयी मूर्ती हो।"]],[177,["अभी कृष्ण को देखिए, उनको तो जल्दी-जल्दी","गुस्सा आ जाता था।"]],[183,["वो अगर किसी को देखते कि कोई पापी है और","उसने पाप किए, उसको ठीक-ठाक थोड़ी","करते थे वो।"]],[190,["एक उन्होंने सुदर्शन चक्र चलाया और ख़तम","उसकी गर्दन गई।"]],[194,["श्री राम को देखिए रावण का उद्धार उन्होंने","उनका वध करके ही किया।"]],[204,["क्राइस्ट को देखिए दूसरी उनकी चरम सीमा कि","उन्होंने क्रूस पे अपने को लटका लिया।"]],[211,["सबकी ज़रुरत थी, ये सब कार्य की ज़रुरत थी -","वो वक्त ऐसा था, समय था, जिसके अनुसार","कार्य होता था।"]],[219,["आज कलयुग में ऐसा इंसान चाहिए कि जो बहुत","शांतिपूर्ण, धीरज से, संभाल के, प्यार से, लोगों","को इस परमात्मा की नाव में बिठा दे।"]],[231,["अब आप लोग कोई अपनी माँ से अपरिचित नहीं","हैं। दूसरी बात जब जन्मदात्री तो माँ ही होती है।"]],[240,["जब आपको दूसरा जन्म देना है, तो पिता कैसे दे","सकता है? क्या पिता ने भी बच्चे को जन्म","दिया है कहीं?"]],[246,["उसके लिए भी माँ की आवश्यकता है। माँ ही को","कोई कहे कि, \" अच्छा क्यों माँ जन्म देती है,","बाप दे।\""]],[253,["दे देगा? ये तो कार्य माँ ही को करना पड़ता है।"]],[259,["और माँ ही है जो बर्दाश्त कर सकती है बच्चे को","नौ महीने पेट में और वो ही है जो जन्म देकर के"]],[264,["उसको संवार सकती है और बच्चा बड़ा होकर","के उसको दुत्कारता भी रहे, तो भी उसको","आशीर्वाद देती रहती है।"]],[273,["लेकिन ये मुसलामानों के असर से शायद यहाँ","लोगों में ये आ गया है कि, आदमी जो है,","ऊँचा है, औरत जो है, नीची है।"]],[280,["कोई भी ऊँचा-नीचा नहीं है। जिस शक्ति से पंखा","चलता है, वो शक्ति भी बहुत ज़रूरी है और","पंखा भी ज़रूरी है।"]],[287,["असल में बात ये हो गई है कि अब जो शक्ति है,","वो चाहती है कि मैं पंखा हो जाऊँ।"]],[292,["और पंखा चाहता है मैं शक्ति हो जाऊँ। जिसका","जो काम करने का है, वो ही करने का है।"]],[298,["ये तो कुछ भी नहीं। विलायत में तो लोग ये","कहते हैं कि, \"माँ, तुम क्यों करती हो?\""]],[303,["तो मैंने कहा, 'बेटे, तुम आ के करो।","ये तो बेकार का काम। मुझे इसमें कोई"]],[308,["थैंकलेस जॉब जिसे कहते हैं, वैसा मैं कर रहीं हूँ,","उसमें फ़ायदा मेरा क्या होता? तुम करो न।","तुमसे होता तुम करो।\""]],[316,["तो इस प्रश्न का सिर्फ दूसरा ही अर्थ","एक माँ की तरफ से मैं लगा सकतीं हूँ,"]],[320,["कि बच्चों में मेरे प्रति अत्यंत सहृदयता है, प्रेम है,","और वो सोचते हैं कि माँ क्यों इतनी मेहनत","करे, पिता करे।"]],[329,["लेकिन जो काम माँ कर सकती है अगर वो पिता","नहीं कर सकता, तो माँ को ही करने दीजिए,","उसमें क्या हर्जा है।"]],[334,["क्या आप पिता से कहते हैं कि, ' तुम खाना","बनाओ।' चार दिन में भूखे मर जाइएगा।"]],[340,["और इस देश में जहाँ कि हम माँ को जानते हैं","और माँ की महत्ता को पहचानते हैं, वहाँ तो","ऐसा सवाल उठना ही नहीं चाहिए।"]],[351,["और आखिरी कौन सा प्रश्न पूछा था?","सहज योगी: ध्यान के बारे में पूछ रहे।"]],[358,["श्री माताजी: ऐं?","सहज योगी: ध्यान के बीच में कईयों को","श्री माताजी: निर्विचारिता"]],[362,["सहज योगी: आँखों में से पानी निकलता है, कोई","हाय निकलती है, कुछ ऐसी चीज़ें","श्री माताजी: हाँ।"]],[366,["जब आपकी आँख से पानी निकल रहे हैं, तो कोई","बुरी बात नहीं है, क्योंकि आपके अंदर बहुत","दबी हुई भावनाएं हैं।"]],[374,["जहाँ आपको प्यार मिलना था प्यार","नहीं मिला - आप दुखी हैं।"]],[379,["हमेशा आप देखिए अपनी माँ के आगे मनुष्य रो ही","देता है, चाहे वो दिखाए, चाहे नहीं दिखाए।"]],[385,["आपने लाल बहादुर शास्त्री के/को बारे में सुना","होगा कि वो अपनी माँ के परम भक्त थे।"]],[391,["और रोज़ सवेरे चार बजे उठ करके सब बत्तियाँ","बुझाते थे कि सरकारी बत्तियों का खर्च न हो।"]],[397,["उसके बाद अपनी माँ के बिस्तर में घुस के सोते थे","थोड़ी देर और अपनी माँ के आशीर्वाद लेते थे।"]],[405,["उनकी माँ भी बहुत पहुँची हुई स्त्री थीं।"]],[408,["हर आदमी जो बहुत ऊँचा उठ जाता है, उसके","पीछे या तो उसकी पत्नी होती है, या उसकी","माँ होती है।"]],[417,["पर जब वो स्त्री आदमी के आगे दौड़ने की","कोशिश करती, तभी गड़बड़ हो जाता है।"]],[426,["सहज योग में स्त्री का स्थान और पुरुष का","स्थान निबिद्ध है। एक दूसरे .."]],[434,["[अलग से] क्या आप उनके लिए कुर्सी ला सकते","हैं, अगर वह नीचे नहीं बैठ सकते हैं। हम्म।"]],[442,["नहीं ठीक है ठीक है, बैठने दीजिए","- एक कुर्सी मँगा लीजिए। कुर्सी, अगर","वो नहीं बैठ सकते। हाँ।"]],[448,["सो हर एक का स्थान निबिद्ध है। ऐसा नहीं है","कि औरत आदमी बन जाएगी, आदमी औरत","बन जाएगा।"]],[454,["जो हमारे यहाँ शिक्षा पहले थी, कि स्त्री,","स्त्री की जगह है, पुरुष, पुरुष की जगह है।"]],[460,["'यत्र नार्या पूज्यन्ते, तत्र रमन्ते देवता।'"]],[464,["स्त्री की पूजा होनी चाहिए, लेकिन स्त्री को","भी पूजनीय होना चाहिए।"]],[468,["फिर इस राजस्थली में, जहाँ पद्मिनी जैसी औरतें","हो गईं, आप लोग क्या बातें कर रहे हैं?"]],[474,["आपके इतिहास में एक से एक राजपूतनी हो गईं,","क्या आप लोग सब भूल गए?"]],[480,["राणा प्रताप को उनकी बीबी ने क्या सीख दी थी?","हमारे यहाँ एक से एक स्त्रियाँ हैं"]],[486,["यहाँ की राजपूत की तो, राजपूतनी जो हैं, उनके","तो कितनी बड़ी-बड़ी कथाएं हैं संसार में हैं।"]],[492,["इतनी वीरश्रीपूर्ण जो औरतें जहाँ हो गईं, वहाँ","आप क्या बात पूछ रहे हैं औरतों की।"]],[497,["ये तो मुसलामानों का कुछ असर आ गया है इस","वजह से आप लोग ऐसा कह रहे होंगे और","तो मुझे समझ में नहीं आता है।"]],[506,["जो राजपूताना के रहने वाले लोग हैं, राजस्थली","के रहने वाले लोग, वो नहीं पूछेंगे।"]],[511,["हाँ, उधर के, बाहर के, अब पंजाब के लोग हैं,","जैसे उन पे मुसलामानों का बड़ा असर है"]],[515,["सिंध के लोग हैं, वो तो बिल्कुल ही उस मामले में -","लेकिन राजस्थान के लोग तो अपने इतिहास","को पहचानते हैं।"]],[522,["अपना इतिहास आप भूल गए क्या? क्षत्राणी","मानी जातीं थीं न यहाँ की, अच्छा बताइए?"]],[540,["अच्छा फिर निर्विचारिता पे पूछा। निर्विचार होने","का मतलब ये है कि हमारे अंदर जो विचार","उठते हैं,"]],[547,["एक उठता है दूसरा गिर जाता है, उठता है गिर","जाता है - हम उसका गिरना शायद देख लें","लेकिन उसका उठना नहीं देख पाते हैं।"]],[556,["इन दोनों विचारों के बीच में एक स्थान है","जिसे विलम्ब संस्कृत में कहते हैं।"]],[562,["हम लोग इन विचारों की जो शिखर है, उस शिखर","पे ही कूदते रहते हैं, इसलिए या तो हम अगला","सोचते हैं या पिछला सोचते हैं।"]],[575,["गत सोचते हैं या भविष्य सोचते हैं। न तो गत अब","रह गया वो तो ख़त्म हो चुका, और जो भविष्य है,","वो सामने है ही नहीं।"]],[585,["जो है सो आज वर्तमान, आज, अभी, इस वक्त, ये","समय। इस वक्त हम खड़े नहीं हो सकते हैं ।"]],[592,["और इसी समय में जो कुछ जानने का है,","पूरा का पूरा जाना जा सकता है।"]],[596,["लेकिन इस वक्त हमारा ध्यान ही जब इसमें नहीं है,","जब हमारा चित्त ही इस क्षण पे टिका हुआ नहीं है,","तो हम कैसे जान सकते हैं?"]],[605,["क्योंकि हमारा चित्त बंटा हुआ है -","या तो गत में है या भविष्य में है।"]],[610,["इस वक्त हम कहें कि आप अपना चित्त रोक","लीजिए, आप रोक नहीं सकते हैं।"]],[615,["जब कुण्डलिनी जागरण होता है तो ये विचारों","के बीच का जो विलम्ब का स्थान है,"]],[620,["वहाँ पर जा कर के आपका जो चित्त है वो रुक","जाता है इसलिए आप निर्विचार हो जाते हैं।"]],[626,["विचार आप करना चाहें तो कर सकते हैं, पर अब","जो विचार आप करेंगे, ये प्रेरणात्मक होंगे"]],[635,["क्योंकि इसमें आत्मा का प्रकाश होगा।","अब आप सामने हमारे बैठे हैं, समझ लीजिए।"]],[642,["हमारी बात छोड़िए, लेकिन आप लोग जो हैं","यहाँ, आये हुए हैं, ये भी बता सकते हैं"]],[649,["कि आपकी कुण्डलिनी का कहाँ रुकावट हो","गई है, आपकी कुण्डलिनी कहाँ बैठी हुई है,"]],[655,["इसका जागरण क्यों नहीं हो रहा है।","आप खुद स्वयं के बारे में कुछ नहीं जानते हैं।"]],[661,["ये आपके चक्रों के बारे में बता सकते हैं,","अपने चक्रों के बारे में बता सकते हैं।"]],[665,["जैसे कोई साहब ने आ के मुझसे कहा सहज योगी","ने कि, \"माँ, मेरा अग्न्या चक्र पकड़ा है,"]],[671,["सामने में आज्ञा पकड़ रहा है।\" इसका मतलब","है, 'मेरे में अहंकार बढ़ गया है।'"]],[676,["लेकिन ऐसे आप किसी से कहो कि, 'आपका","अहंकार बहुत बढ़ गया है,' तो वो मारने","को दौड़ेगा।"]],[682,["अगर उसमें वाकई अहंकार है, तो और भी पीटेगा।"]],[686,["लेकिन स्वयं ही आप अपने अंदर के दाग जैसे","देखे जाते हैं, अपने साड़ी के अंदर के दाग"]],[692,["अगर मैं देख लूँ, तो मैं नहीं चाहूँगी कि मेरी","गन्दी साड़ी रहे, उसको मैं धो डालूँगी।"]],[696,["अगर मैं देख ही नहीं सकती हूँ, अंधकार में","बैठी हूँ, तो मैं नहीं चाहूँगी कि कोई कहे कि,","'तुम्हारे अंदर दाग लगा हुआ है।'"]],[702,["यही आज का सहज योग है कि सबसे पहले","कुण्डलिनी का जागरण कर दो।"]],[708,["हाँ सफाई करते रहो, एक-एक चक्रों की","सफाई करते रहो, ये करो, वो करो।"]],[712,["कितने सालों से होते ही आया है - मैंने कहा","कि चलो सबको पहले जागृत कर दो।"]],[717,["फिर उस टिमटिमाते प्रकाश में आप ज़रूर देख","लीजिएगा कि आप के अंदर कौन सा दोष है।"]],[723,["आप ही अपना दोष खुदही ठीक कर लें।"]],[727,["गर साँप को हाथ में पकडे हैं, कितना भी","कहो आप साँप छोड़ेंगे नहीं।"]],[731,["ठीक है थोड़ा सा प्रकाश दे दो, साँप","अपने आप छूट जायेगा।"]],[738,["अब विलायत में आप जानते हैं कि कितना","लोग ड्रग्स वगैरा लेते हैं।"]],[744,["एक रात के अंदर उनका सब छूट गया","- सो कैसे घटित हुआ?"]],[752,["आज पार हुए, कल साफ़।"]],[759,["क्योंकि प्रबल इच्छा उनको परमात्मा की","ओर उठने की थी।"]],[762,["जितने अधोगति में हैं, उतने ही ज़ोर से वो","परमात्मा की ओर उठना चाहते हैं।"]],[767,["और हम लोग ऊर्ध्वगति पर चल रहे हैं,","लेकिन दोनों तरफ कूदते हैं।"]],[771,["अधोगति पे भी जाते हैं, ऊर्ध्वगति पे भी जाते हैं।","परमात्मा के नाम लेते हैं, उसके बाद गालियाँ शुरू।"]],[778,["वो लोग परमात्मा का नाम वगैरा कुछ नहीं लेते,","परमात्मा को जानते नहीं, माँ को जानते नहीं","- अधोगति में चले गए हैं।"]],[784,["अब जान रहे हैं कि हम अधोगति में हैं, तो उसमें","से निकलने के लिए पूरी कोशिश करते हैं,"]],[788,["और ज़रा सा हाथ मिलते ही खिच आते हैं ऊपर","में, क्योंकि वो भी कोशिश करते हैं।"]],[792,["लेकिन हमारे यहाँ के जो लोग हैं, भारतवर्ष","के, वो यह मेहनत नहीं करते हैं।"]],[798,["जो ये लोग मेहनत कर सकते हैं, वो मेहनत हम","लोग नहीं करते। पार तो बहुत हो जाएँगे।"]],[803,["आज देखिएगा, आज सारे के सारे हो जाएँगे","पार, लेकिन जमना कठिन काम है।"]],[809,["क्योंकि उसके प्रति जो एक तरह की श्रद्धा होनी","चाहिए और अपने आत्मसाक्षात्कार के प्रति","जो आदर होना चाहिए, वो नहीं है।"]],[820,["इसीलिए बुद्ध ने कहा कि, 'आत्मसाक्षात्कार होने","के बाद सब सन्यासी हो जाओ तो अच्छा है।'"]],[825,["नहीं तो फिर मेरे बीबी, तो मेरा बच्चा, तो मेरा घर,","तो मेरे भाई, तो फलाने, तो ढिकाने - उधर","ही चित्त बटता जाता है।"]],[833,["पर क्योंकि माँ बैठी हुई सामने तो वो सभी","देखती रहती है, 'चल भाई, तेरे माँ बीमार,"]],[838,["उसको भी ठीक कर देते हैं, बाप है उसको भी","ठीक कर देते हैं, रिश्ता भी ठीक कर देते हैं,"]],[842,["शादी का मामला भी ठीक कर देते हैं, ये भी कर","देते हैं, वो भी कर देते हैं - सब चीज़","साथ-साथ चल रही है।"]],[848,["लेकिन जिस चीज़ को हम बहुत छोटा सा","समझ रहे हैं, बहुत बड़ी चीज़ है।"]],[852,["आज सारे सृष्टि में आप देखिए कितनी","आफ़त मची हुई है।"]],[857,["परमात्मा ने इतनी सुन्दर सृष्टि बनाई और मनुष्य","ने उसको कितना धूसर कर दिया है, ख़राब","कर दिया है।"]],[863,["कहीं सुख, आनंद किसी को नहीं है। ऐसा आज","समय आया हुआ है कि इस वक्त अगर हमने"]],[870,["इस, अपने दिव्यता को नहीं पाया, अपनी दैवी","शक्ति को नहीं पाया, तो सर्वनाश की बात है,","सर्वनाश की बात है।"]],[880,["सारे दुनिया की जितनी मानव जाति है,","उसका उद्धार करने की बात है।"]],[886,["उसमें आपको मेहनत करनी पड़ेगी, उसमें आपको","खुद को बनाना पड़ेगा, पनपाना पड़ेगा,","तब जाकर के काम बनने वाला है।"]],[901,["और आपको आश्चर्य होगा कि इसका उत्तरदायित्व,","इसकी ज़िम्मेदारी, आप भारतीय लोगों पर है।"]],[908,["साइंस की ज़रूर उन लोगों पर है, लेकिन परमात्मा","के साइंस की ज़िम्मेदारी आप लोगों पर है।"]],[917,["आप लोगों को ही इसके बारे में, इसके ज्ञान","के बारे में, जागरुक होना पड़ेगा।"]],[923,["और समझना पड़ेगा कि ये जो जड़ों का ज्ञान है","ये क्या है। ये हमारे देश में अनंत काल से","गुप्त रूप से आया है।"]],[933,["इसकी वाच्याता सबसे पहले आदि शंकराचार्य","ने की, ऐसा कहना चाहिए।"]],[938,["पर मार्कण्डेय आदि सब लोगों ने कुण्डलिनी","के बारे में काफ़ी कहा हुआ है। लेकिन हम","कहाँ मार्कण्डेय को पढ़ते हैं?"]],[945,["शंकराचार्य को भी पढ़ेंगे एक, लिखेंगे दूसरा, कहेंगे","तीसरा, इस तरह का हाल मैं देखती हूँ किताबों में।"]],[952,["कोई भी आदमी ने उनको सही मायने में समझा","नहीं, लिखा नहीं, और सब लोग इनको इस्तेमाल","करते हैं पैसा बनाने के लिए।"]],[961,["धर्म बनाने के लिए नहीं, और महा मानव बनाने","के लिए नहीं। आप लोगों को महा मानव बनना है।"]],[969,["उसके लिए सिर्फ एक नम्रता से स्वीकार करना","चाहिए अपनी स्वयं की सम्पदा।"]],[976,["या आपकी अपनी सम्पदा है उसको एक","नम्रता पूर्वक स्वीकार करना चाहिए।"]],[984,["अब कोई सवाल हो तो पूछ लीजिए और।"]],[987,["आज शाम को तो चक्रों के बारे में मैं बताने ही","वाली हूँ आप लोगों को एक-एक, एक-एक","चक्र के बारे में।"]],[993,["क्या चक्र है इसको आप सीख लीजिए।"]],[996,["किसी भी विद्यार्थी को जब आप स्कूल में भर्ती","करते हैं तो वो एक जिज्ञासु के रूप में देखता है"]],[1004,["कि मुझे क्या-क्या जानना है -","अभी मैंने कुछ नहीं जाना है।"]],[1009,["अभी डॉक्टर साहब हैं, बता ही रहे थे आपसे","कि बहुत गुरुओं के पास गए लेकिन","कुछ भी जाना नहीं था।"]],[1018,["और यही जो जानना है, इसी को कहा गया है, शुरू","में ही श्री कृष्ण ने, कि ज्ञान को प्राप्त करो।"]],[1030,["भक्ति में भी उन्होंने - आज मैं बताने","वाली हूँ, श्री कृष्ण की राजनीति।"]],[1039,["श्री कृष्ण जो थे वो हमारे मस्तिष्क में रहते","हैं - वो सारे विराट का मस्तिष्क हैं।"]],[1048,["अत्यंत चतुर और बुद्धिमान। सारा चातुर्य","संसार का उन्हीं से आता है।"]],[1054,["और चतुराई ये, कि वो समझ गए कि इनकी","खोपड़ी में आसानी से चीज़ जाने नहीं वाली,","तो टेढ़ी उँगली घी निकालना पड़ेगा।"]],[1062,["लेकिन उसको समझने के लिए भी, जब तक","आपमें आत्मसाक्षात्कार नहीं होगा,"]],[1067,["आप कृष्ण को भी नहीं समझ पाएँगे क्योंकि","वो टेढ़ी खीर हैं।"]],[1072,["लेकिन माँ तो साफ़-साफ़ बात बता देगी कि","कृष्ण क्या कह रहे थे।"]],[1078,["जब उन्होंने आपसे कहा कि आप भक्ति करिए,","तो उन्होंने कहा है, 'पत्रं, पुष्पम, फ़लम, तोयं'"]],[1092,["'सब कुछ मैं ले लेता हूँ।' और देने के समय एक","शब्द पे आपको खिला गए हैं, 'लेकिन","तुम अनन्य भक्ति करो।'"]],[1102,["अनन्य शब्द का अर्थ अगर कोई भी संस्कृत","समझने वाला हो, जब दूसरा नहीं होता है।"]],[1109,["माने आत्मसाक्षात्कार के बाद भक्ति करो - साफ़","कह गए। वो कोई दुकानदार नहीं थे, तो पहले","ही उन्होंने बढ़िया चीज़ कह दी,"]],[1118,["कि, 'ज्ञान को प्राप्त करो।' ज्ञान माने ये","नहीं पढ़ना-लिखना।"]],[1124,["पढ़ने-लिखने से कोई आदमी आपने सुना है कि","वो आत्मसाक्षात्कारी हो गया - उल्टा","ग़ुस्सेला हो जाता है।"]],[1133,["तो उन्होंने ये कहा कि, 'आप ज्ञान को प्राप्त करो,'","- माने अपनी जो नसें हैं, जिसे सेंट्रल नर्वस","सिस्टम कहते हैं, उसमें जानो परमात्मा को।"]],[1143,["यही विद है, इसी से वेद शब्द आया है,","यही ज्ञान है।"]],[1151,["परमात्मा को अपने उँगलियों पे जानना होगा,","ऐसे मोहम्मद साहब ने कहा है।"]],[1157,["'जब उत्थान, रेसुररेक्शन का समय आएगा,","तब आपकी उँगलियाँ बोलेंगीं,' ऐसे","मोहम्मद साहब ने कहा है।"]],[1166,["श्री कृष्ण ने भी सबसे पहले यही बात कही। भक्ति","के लिए अनन्य पे नचा दिया, और कर्म के लिए","फिर नचा दिया आपको।"]],[1175,["कहा कि, 'सब कर्म करो और परमात्मा के चरणों","में रखो।' हो ही नहीं सकता है।"]],[1184,["ये बेवक़ूफ़ बनाने की बात हुई। हो ही","नहीं सकता है।"]],[1188,["जब तक आपके अंदर अहंकार है, आप कभी भी","कोई सा भी कर्म करने पर, यही सोचिएगा कि,","हमीं कर रहे हैं।"]],[1195,["लेकिन जब आप पार हो जाएंगे, तो आप क्या","कहिएगा कि, 'ये हो रहा है माँ, जा रहा है,","बन रहा है।'"]],[1204,["'इनका नहीं होता है।' आप ये नहीं कहते कि,","'मैं कर रहा हूँ। मैं कुण्डलिनी उठा रहा हूँ,'","ऐसे नहीं कहते आप।"]],[1214,["आप कहते हैं, 'उठ नहीं रही।' तृतीय पुरुष","में बातचीत शुरु हो जाती है।"]],[1219,["'तू ही, तू ही, तू ही,' जो कबीर ने कहा है,","वो शुरु हो जाता है।"]],[1225,["जब तक आपकी कुण्डलिनी जागृत नहीं होगी, तब","तक आप कर्म का फल परमात्मा पे डाल ही","नहीं सकते"]],[1232,["लेकिन कुण्डलिनी जागरण के बाद हटात आप","डाल ही देते हैं। कहते ही नहीं बनता दूसरी चीज़।"]],[1244,["अब कोई आदमी का नहीं हो रहा है, तो कहेंगे,","\"भई हो नहीं रहा क्या करें।\""]],[1248,["\"इनका तो ये गड़बड़ है, उनका तो वो गड़बड़ है,","कुछ पाप करम होएंगे, कुछ और गड़बड़","होएगी, कोई बात होएगी।\""]],[1253,["अब बोल भी सकते नहीं, \"ये चक्र पकड़ रहा है,","वो चक्र पकड़ रहा है, ये होगा,'"]],[1258,["लेकिन ये नहीं कहेंगे कि, 'मैं कर रहा हूँ'","- 'मैं' छूट गया।"]],[1271,["'कहे नानक बिन आपा चीन्हे मिटे न भ्रम की काई।'","अब वो रट रहे हैं, अखंड पाठ कर रहे हैं।"]],[1279,["अरे, उसमें जो लिखा है उसका क्या तुम","पाठ कर रहे हो?"]],[1286,["वो अखंड पाठ रामायण का हो रहा है,","अखंड पारायण महाराष्ट्र में गुरु चरित्र","का होता है, अखंड होते रहता है।"]],[1295,["कुछ थोड़ा खंड पढ़ें तो अच्छा हो। मनुष्य","कमसकम विचारे तो कि इसमें क्या","लिखा है, क्या मैं पढ़े जा रहा हूँ।"]],[1303,["ऐसे रटने से कहीं परमात्मा नहीं मिलते।","वही हाल पूजा पाठ का है।"]],[1313,["आप देखते हैं जो लोग पूजा पाठ करते हैं, वो","इतने क्रोधी होते हैं कि भगवान बचाये रखे।"]],[1317,["जिसने जिस दिन हनुमान जी का व्रत रखा उस दिन","भाग खड़े होना चाहिए। उन पर पहले हनुमानजी","उतर आते हैं।"]],[1324,["हालाँकि हनुमानजी इतने कृपालु और इतने सुन्दर","हैं लेकिन उनके भजन करने वाले लोगों से","भगवान बचाये रखे।"]],[1332,["तो अपने बच्चे पूछते हैं कि, \"ऐसे भगवान से","फायदा क्या भई, ऐसे भगवान को क्यों मानते हो\""]],[1337,["\"जहाँ कि बस ब्राह्मणों को पैसा चढ़ा रहे हो,","और तो कुछ फ़ायदा हो नहीं रहा है।\""]],[1343,["उनके सामने सिद्ध करना होगा कि जब परमात्मा","मिल जाते हैं तो, अंदर से परिवर्तन हो जाता है।","परिवर्तन होना चाहिए।"]],[1353,["हमारे यहाँ पक्षी को कहते हैं द्विजः और ब्राह्मण","को कहते हैं द्विज। जिसने ब्रह्म को जाना","सो ही ब्राह्मण है।"]],[1360,["नहीं तो वाल्मीकिजी ब्राह्मण कैसे हुए और व्यासजी,","जिनकी आप गीता रोज़ पढ़ते हैं, वो कैसे ब्राह्मण","हुए। सीधा हिसाब है।"]],[1367,["कोई बुरा माने चाहे भला माने बात सही ये है कि,","जब तक आपका आत्मसाक्षात्कार नहीं हुआ है,","आप ब्राह्मण कहलाने लायक नहीं हैं।"]],[1374,["अब ब्रह्म को जानना - तो द्विज पक्षी को भी","कहते हैं, ब्राह्मण को भी कहते हैं"]],[1380,["वजह ये है कि 'द्वी: जायते'; जिसका दो बार जन्म","होता है, वो पक्षी वो पहले अंड स्वरुप होता है","और फिर पक्षी स्वरुप हो जाता है"]],[1388,["इसी प्रकार जो मनुष्य पहले मानव स्वरुप होता","है और फिरआत्मसाक्षात्कारी योगी स्वरुप होता है,"]],[1394,["ये उसका दूसरा स्वरुप जब तक नहीं, परिवर्तन से","जब तक न आये - ये नहीं कि लगा लिया अपने","ऊपर कि, 'मैं महायोगी हूँ' - एक इश्ताहरात।"]],[1403,["इसमें इश्तेहार लगाने की बात नहीं, अंदर से जो","परिवर्तित होता है, वो आदमी दिखाई देता है।"]],[1412,["मैं तो आज हैरान हो गई कि डॉक्टर निगम ने बात","करी; मैं तो इनकी कभी ख़ास आवाज़ भी नहीं","सुनी थी।"]],[1418,["परसों इन्होंने कहा कि, \"मेरी एकदम विशुद्धि","खुल गई,\" तो मैं आज आश्चर्यचकित हुई इनकी आवाज़ सुनके"]],[1422,["कि निगम साहब इतने ज़ोर-ज़ोर से बोल रहे","हैं - नहीं तो आवाज़ नहीं सुनी थी।"]],[1426,["विशुद्धि खुलते ही साथ देखिए क्या कमाल हो गया!","जो कभी गाना नहीं गाते थे वो बढ़िया गाना","गाने लग गए,"]],[1433,["जो कभी चित्र नहीं बनाते थे वो बड़े भारी आर्टिस्ट","हो गए - कहाँ से कहाँ लोग पहुँच गए।"]],[1438,["और सब आनंद में विभोर संतुष्ट बैठे हुए हैं।","लेकिन थोड़ी सी पुण्याई तो होनी ही चाहिए।"]],[1445,["अब आप कहिए कि, 'माँ हिटलर को आप जागृति","दीजिए,' तो बहुत मुश्किल काम है भाई।"]],[1449,["और मैं क्यों हिटलर को देने जाऊँ? मेरे भक्त","बहुत हैं उन्हीं को मैं दूँगी कि नहीं।"]],[1457,["अब इंग्लॅण्ड में इतनी मेहनत कर ली,","मेरा तो जी ऊब गया है"]],[1461,["मैं इन लोगों से कहती कि, 'भई मेरी छुट्टी करो,","मेरे देश में हज़ारों लोग पड़ें है, उनको मुझे","पार करने दो - ये तो बेकार के लोग हैं।\""]],[1467,["और दिल्ली वालों से भी कहना है कि अगर जल्दी","वहाँ के लोग ठीक नहीं होते मुझे वहाँ और","लोगों से झूझना नहीं है।"]],[1474,["वहीं महाराष्ट्र दूसरी बात है। ऐसी राजस्थली भी है।"]],[1478,["हो सकता है कि राजस्थान महाराष्ट्र आदि देशों","में अगर सहज योग जम जाये, तो दिल्ली वालों","की खोपड़ी भी ठीक आ जाएगी।"]],[1490,["साधक: अभी प्रैक्टिस कराएँगीं?","श्री माताजी: आ?"]],[1493,["साधक: प्रैक्टिस करवाएँगीं?","श्री माताजी: हाँ ठीक है।"]],[1495,["और कोई सवाल हो तो पहले पूछ लीजिए।","सवाल बहुत ज़रूरी होते हैं।"]],[1498,["प्रैक्टिस अभी करा .....","पानी ज़रा सा चाहिए था मुझे।"]],[1513,["साधक: इसमें अभ्यास क्या होना चाहिए?","श्री माताजी: ऐं?"]],[1515,["साधक: रोज अभ्यास क्या होना चाहिए?","श्री माताजी: हाँ, रोज का अभ्यास। वो भी बता रहे।"]],[1519,["देखिए बात ये है, इतने आश्चर्य की बात है -","अब आप लोगों से बताने में कोई हर्ज़ नहीं"]],[1526,["कि ये आपका कैमरा है न, ये आपसे ज़्यादा दृष्टि","रखता है और ऐसे-ऐसे हमारे चित्र आये हैं"]],[1536,["कि आप आश्चर्यचकित हो जाएंगे। कहीं-कहीं","तो हमारे अनेक हाथ तक आ गए।"]],[1543,["और एक बार ऐसे हाथ ऊपर किया था तो यहाँ से","लाइट निकल कर के, अनेक उसकी धाराएँ बन के,","उसके ॐ भी लिख कर आ गया।"]],[1551,["एक बार आकाश में इसी तरह से स्विट्ज़रलैंड","में उन्होंने देखा कि प्रकाशमय एक बड़ा सा","बादल आया"]],[1558,["और उससे बहुत सी शाखाएं निकल के","दो बादल बन गए।"]],[1562,["उन्होंने बादलों के फोटो लिए तो एक में गणेश जी","और एक में पूरा हमारा फोटो, यहाँ तक की नाक","की ये, और दाँत का ये तक।"]],[1570,["और दूसरे में एक हमारा फोटो है, जैसे वही","फोटो उसमें से निकलता आ रहा है।"]],[1575,["तो ये कैमरा के चमत्कार हो रहे हैं। तो ये है कि","सृष्टि बहुत चीज़ों से जता रही है कि अब समय","आ गया है और आप ये काम करा लीजिए।"]],[1584,["इसी प्रकार हमारे फोटो में भी चैतन्य है। ये एक","कमाल हो गया है कैमरा के कि फोटो में चैतन्य है।"]],[1591,["तो इस फोटो में भी अब आप देख रहे हैं, इस फोटो","में भी चैतन्य है। जैसे हम कहते हैं कि एक","मूर्ति होती है,"]],[1602,["जो स्वयंभू मूर्ति होती है, उसमें से चैतन्य होता","है, उसी प्रकार इस फोटो में से चैतन्य है।"]],[1611,["तो फोटो को पहले आपको इस्तेमाल आलम्बन","लगता है, उसको करना पड़ेगा।"]],[1616,["अब उसमें भी अहंकार लोगों को हो जाए कि हम","अपना ही फोटो क्यों न लगाओ,"]],[1619,["तो लगा लो भाई, लेकिन होता नहीं ना काम।","तो हमारे फोटो में चैतन्य है, उससे","आप इस्तेमाल करिए।"]],[1628,["उसको इस्तेमाल करने का तरीका बहुत आसान है,","कि उसके सामने एक दीप जला लें और दोनों","हाथ उसके ओर ऐसे करके बैठिए।"]],[1639,["और अगर आपके हाथ के अंदर कुछ ठंडक सी","महसूस हो रही है,"]],[1643,["तो ये जान लें कि इस हाथ में ज़्यादा हो रही,","इस हाथ में ज़्यादा हो रही।"]],[1649,["समझ लीजिए आपके इस हाथ में ज़्यादा","हो रही है और इसमें कम हो रहा है।"]],[1654,["इसका मतलब है आपकी जो लेफ्ट साइड है,","वो कमज़ोर पड़ गई। ज़ाहिर है।"]],[1661,["तो उस वक्त में आप लेफ्ट हैंड हमारे फोटो की","ओर करिए, ज़मीन पे बैठ जाइए, और राइट","हैंड ज़मीन पे रख दीजिये।"]],[1672,["तो लेफ्ट में शक्ति दौड़ना शुरू हो जाएगी।","यहाँ से गुज़र कर के वो ज़मीन के अंदर","चली जाएगी।"]],[1679,["समझ लीजिए राइट हैंड में कम है। तो आप राइट","हैंड हमारे ओर करिए, सामने एक दीप रखिए -","दीप नहीं।"]],[1688,["लेफ्ट हैंड जिस वकत रखिए तब दीप रखिए","और जब राइट हैंड रखें तब दीप नहीं रखें।"]],[1694,["तब आप राइट हैंड हमारे ओर करिए, लेफ्ट हैंड","ऊपर की ओर करें और पानी, जल तत्व नीचे","रख के उसमें थोड़ा नमक डाल दें।"]],[1702,["उससे आपकी सफाई हो जाएगी राइट साइड की।","ये सब लिखा हुआ है किताब में, मेरे विचार से।"]],[1710,["लिखा है? अच्छा। फिर दोनों हाथ फोटो की ओर","करें और देखें दोनों हाथ में एक जैसा आ","रहा है क्या।"]],[1719,["अगर वैसा शुरू हो जाए, तो फोटो के आगे रोज़","रात को सोने से पहले एक दीप जला देने का"]],[1725,["दोनों हाथ फोटो की तरफ, फोटो को देखते रहें","और दोनों पैर पानी में, नमक डाल के गरम,","गुनगुना, जैसा चाहें वैसा पानी"]],[1736,["या ठंडा, एक पाँच मिनट उसमें बैठने पर हाथ","में जब झर-झर, झर-झर चैतन्य बहना","शुरू हो जाए,"]],[1743,["और सर में से भी चैतन्य निकलना शुरू हो जाए,","तो पैर पोछ कर के, चित्त यहाँ रख के सो जाएँ।"]],[1750,["फिर सवेरे बाहर जाने से पहले","फोटो के आगे थोड़ी देर ध्यान करें"]],[1756,["और अपने को माँ के कवच में डालें -","उसे हम लोग बंधन कहते हैं।"]],[1761,["इस तरह से घुमा कर के कवच कैसा देना","- आपने बताया डॉक्टर साहब? कवच डाल दें।"]],[1766,["और कुण्डलिनी का जागरण फिर से एक बार","कर के बाहर चले जाएँ।"]],[1771,["जैसे किसी आदमी से आपको मिलना है और वो","आदमी ठीक नहीं है, उसका नाम हाथ में","झूठ-मूठ लिख लीजिए।"]],[1779,["झूठ-मूठ लिख कर के उसको ... हाथ में जैसे","किसी का नाम आपने लिख लिया, लिखने के बाद","- झूठ-मूठ का।"]],[1795,["उसको इस तरह से घुमा देने का। और तीन बार","माँ, माताजी, जो भी कहना चाहो,"]],[1802,["श्री माताजी कहना चाहो तो, ऐसे कर के तीन बार","उसे निकाल के फेंक दीजिए।"]],[1807,["अब ये प्रेम की शक्ति आप इस्तेमाल कर रहे हैं।","हाथ से आपके ये प्रेम की शक्ति बह रही है।"]],[1812,["उस आदमी के ह्रदय में आपके प्रति एक","सहानभूति और प्रेम आ जायेगा।"]],[1817,["अभी तक तो हम लोगों ने द्वेष की शक्ति इस्तेमाल","करी, घृणा की करी, कम्पटीशन की करी है","- ये प्रेम की शक्ति है।"]],[1825,["ऐसे करने से आपको खुद ही हल्कापन","महसूस होगा उँगलियों में।"]],[1830,["ऐसे ही बैठे-बैठे आप जिसके बारे में सोचना चाहें","कि इस आदमी को क्या तकलीफ है,"]],[1835,["इस तरह से आप हाथ करें उस आदमी की ओर,","फोटो सामने रख लें"]],[1839,["- इस आदमी को क्या तकलीफ है","- आपकी उंगलियाँ जड़ होने लग जाएंगी।"]],[1843,["अब समझ लीजिए कि आपकी ये उँगली जड़ हो","गई। इसका क्या मतलब है? इससे कौन","सा रोग हो गया है?"]],[1849,["इस हाथ में रोग का निदान हो जायेगा और","अहंकार का, और इस हाथ में उसकी मानसिक","शक्ति का निदान हो जायेगा।"]],[1858,["इसको थोड़ा सा आप लोग अगर सीख लें, तो","आप बड़े-बड़े सहज योगी हो जाएँ।"]],[1864,["लेकिन सहज योग में बहुत सी बातें समझ लेना","चाहिए। उसमें से एक बात ये भी है, कि हम","विश्व धर्म में अब उतरें हैं।"]],[1874,["पहले धर्म थे, अब ये एक विश्व धर्म है, और विश्व","धर्म में हमको सब धर्म की पूर्णतया इज़्ज़त","करनी चाहिए।"]],[1885,["सबका मान रखना चाहिए। सहज योग में हम","किसी भी धर्म का अपमान नहीं करते हैं।"]],[1890,["और वो सब जो हम अलग-अलग फर्क","लोग समझते हैं, उसको फिर हम जान लेते हैं"]],[1897,["अपने अंदर पूरी तरह से, उसका प्रात्यक्ष देख","कर के, कि वो सब हमारे अंदर स्थित बड़े","महानुभाव अवतरण हैं।"]],[1909,["हम अपने ही से लड़ रहे हैं जब हम गलत फ़हमी","में बैठे हुए हैं। इस गलत फ़हमी से हम","उठ जाते हैं।"]],[1918,["बहुत सी हमारे अंदर गलतफहमियाँ हैं। जैसे","मैं कल ही बता रही थी - सीधी बात है,"]],[1926,["कि हम लोग जिस दिन किसी भी भगवान का","जनम दिन होता है, उस दिन उपवास करते हैं;","ये बहुत ही गलत बात है।"]],[1934,["एक हमारे शिष्य थे गणपति भक्त बहुत, अग्निहोत्री","साहब, उनके घर में बहुत अग्निहोत्र हुए थे,"]],[1939,["बड़े भारी गणपति भक्त हैं, सहज योगी भी थे।","आये, हमें कहने लगे, \"हमें प्रोस्ट्रेट की तकलीफ़।\""]],[1944,["हमने कहा, \"ऐसे कैसे हो सकता है? आप तो","गणपति भक्त हैं और गणपति जो हैं"]],[1948,["प्रोस्ट्रेट ग्लैंड को देखते हैं, आपको प्रोस्ट्रेट की","तकलीफ़ कैसे हो गई?\""]],[1951,["तो कहने लगे, \"माँ हो गई। डॉक्टर ने कहा","ऑपरेशन कराना।\""]],[1954,["तो मैंने कहा, \"अच्छा लो भई,\" हमारा तो प्रसाद","चना है, तो हमने कहा, \"लो भाई प्रसाद खा लो।\"","तो इधर-उधर देखने लगे।"]],[1960,["मैंने कहा, \"क्या बात है?\" कहने लगे, \"आज","माँ संकष्टि है, तो आज उपास करते हैं।\""]],[1964,["मैंने कहा, 'लो।' संकष्टि माने श्री गणेश का","तुम जनम मना रहे हो।"]],[1969,["कोई जनम, जिस दिन तुम्हारे घर में बेटा हो, क्या","तुम लोग उपास करते हो? ये तो सूतक हो गया।"]],[1974,["जब कोई मरता है, तब तो न कोई उपास होता है।","\"तो गणेशजी तुमसे खुश कैसे होंगे?\""]],[1979,["तो मैंने उठा कर के उनको चना दिया।","खा लिया उन्होंने चना।"]],[1986,["वापस पूना गए डॉक्टर ने कहा, \"तुम्हारा","प्रोस्ट्रेट कैसे ठीक हो गया भाई?\""]],[1994,["अब ये देखने वाली चीज़ है। तो हम अपने देवताओं","को ही रात-दिन नाराज़ करते रहते हैं।"]],[2002,["उसके बारे में अगर ज्ञान हो जाए, तो उनको कैसे","संतुष्ट करना चाहिए, ये समझ लेना है।"]],[2009,["ये ज्ञान सूक्ष्म भी है और व्यापक है।","इसमें सभी ज्ञानों का सार है।"]],[2016,["ये तत्वनिष्ठ है। सारों का तत्व जो है,","उस पर पकड़वा देता है।"]],[2021,["उसकी जो बाह्य में जड़ या ग्रॉस, जो कुछ भी चीज़ें","हो गईं, उसको झाड़ कर के, तत्व को खड़ा","करता है।"]],[2027,["और तत्व पे आपको ले आता है। उस तत्व को","आपने समझ लिया, काम बन गया।"]],[2033,["लेकिन उसके लिए खुला दिमाग चाहिए;","खुला दिमाग का आदमी चाहिए।"]],[2038,["जिस आदमी का दिमाग कुंद होगा वो कहेगा, \"नहीं","साहब, मैं तो बस शंकरजी को मानता हूँ और","मैं कृष्ण जी को नहीं मानता।\""]],[2045,["तो उससे हम कहेंगें, \"अच्छा भैया अगले जनम","मिलना, इस जनम तो कुछ नहीं हो सकता है।"]],[2050,["तो ये समझना चाहिए कि आपका सौभाग्य है।","जब माँ बच्चे तो खाना खिलाती है, तो बच्चे","का पेट भरता है ना"]],[2059,["कि माँ का, लेकिन तो भी माँ इस तरह से खिलाती","है कि बच्चा सोचता है कि माँ पे ही उपकार","कर रहा है।"]],[2065,["एक तरह से है भी - कि माँ के प्रेम की पूर्ती हो","जाए, ये माँ पे उपकार ही है।"]],[2071,["लेकिन बच्चे की सूझ-बूझ पर भी बड़ा","निर्भर होता है।"]],[2080,["तो अब थोड़ा सा हम लोग ध्यान कर लें।"]],[2087,["कुछ और प्रश्न है?","साधक: जैसा कल बताया (अस्पष्ट)"]],[2092,["श्री माताजी: क्या कह रहे हैं ?","साधक: विधि, विधि","श्री माताजी: हाँ, अभी तरीका बताते हैं।"]],[2098,["श्री माताजी: ऐं?","सहज योगी: कवच डालना और कुंडलिनी","उठाना, कृपया यह बताएं।"]],[2102,["श्री माताजी: ये बताएँ?","सहज योगी: नहीं बताया नहीं मैंने।"]],[2104,["श्री माताजी: अभी नहीं बताया?","अच्छा मैंने सोचा आप बता रहे थे।"]],[2106,["सहज योगी: नहीं वो बात कर रहे थे","श्री माताजी: अच्छा, पानी दीजिए।","हाँ, मैं बता देती हूँ।"]],[2118,["लीजिए बस। अच्छा।","अब कवच का तरीका कैसा है? सादा है।"]],[2125,["क्योंकि आपके हाथ से अब ये जागृति हो गई","और हाथ से ठंडक-ठंडक बह रही है"]],[2130,["तो आप स्वयं समर्थ हो गए हैं; आप अपने ही को","अपना कवच दे सकते हैं क्योंकि अब शक्ति","बहने लग गई है।"]],[2137,["अब आप, जो मैंने आपसे कल कहा था कि जो","आपका बायाँ हाथ है, माने आपका लेफ्ट हैंड जो है,"]],[2149,["उसको आप फोटो की ओर करें, क्योंकि ये","आपकी इच्छा शक्ति है। समझे न, इच्छा शक्ति है।"]],[2156,["और राइट हैंड जो है, दाहिना हाथ, उसको आप","सर पर से पूरा उठा कर के, पूरा, यहाँ से उठाएँ।"]],[2164,["जैसे आप बैठे हैं तो समझ लीजिए कि घुटने से","लेकर कर के पूरा संभाल के ऐसे ला के छोड़ दें।"]],[2173,["और फिर दूसरे बार फिर उठा के छोड़ दें।","सात बार अगर आप इस तरह से करें तो,"]],[2184,["फिर से करिए, तीन, चार और ये पाँच, छह और","ये सात।"]],[2211,["अब देखिए, सात अर्ध मात्रा से साढ़े तीन","मात्रा बन जाती है। इसका बड़ा गणित है।"]],[2219,["साढ़े तीन कुण्डलिनी के कुण्डलों का बड़ा भारी","गणित है। अब वो कभी समझाएँगे।"]],[2227,["अब रही बात ये जो कुण्डलिनी का जागरण है,","उसको चढ़ाते वक्त ऐसे भी चढ़ा सकते हैं"]],[2242,["लेकिन बेहतर है कि इसको - ये जो कुण्डलिनी","की प्राप्ति की जो इच्छा है, चढ़ाने की जो इच्छा है ,"]],[2253,["इस हाथ से प्रदर्शित करते हुए, इस तरह से","कुण्डलिनी के ऊपर पकड़ी जाए पहले"]],[2259,["लेफ्ट हैंड नीचे। अब ये जो हाथ है इसको घुमाना","है। अब जिसको कहते हैं घडी के काँटे के जैसे,","क्लॉक वाइस।"]],[2274,["ये हाथ सीधा चलेगा और वो हाथ घुमाना है।","उसके लिए आप देखिए कि इस तरह से,"]],[2281,["बिल्कुल ध्यान पूर्वक लेफ्ट हैंड को देखिए और","कंधे ढ़ीले छोड़ कर के, इसको ऐसे-ऐसे ऊपर,"]],[2287,["हाथ की ओर देखते रहें, और हाथ ऊपर तक","ले जाएँ, और फिर ऊपर ले जाकर के"]],[2292,["उसको एक, दो बार अच्छे से घुमा के","बाँध दें। ये पहली बाँध है, पहली गाँठ है।"]],[2301,["ये है महाकाली की गाँठ। अब दूसरी।","अब देखिए हाथ जल्दी उठेगा।"]],[2311,["अब ढीले छोड़ दीजिए कंधे और घुमाइए फिर","से, ये दूसरी गाँठ। ये महासरस्वती की गाँठ है।"]],[2319,["न उल्टा हो रहा है। हाँ ये। और ये हाथ घुमाना","ही नहीं है। जब आप - इसको ही घुमाना है।","इसको सीधे चलाना है।"]],[2327,["इसको घुमाते, घुमाते ऐसे, ऐसे चलाना है, इस","तरह से। अच्छा अब दूसरा।"]],[2332,["तीसरी जो गाँठ है, ये महालक्ष्मी की गाँठ है। पहली","इड़ा, पिंगला और सुषुम्ना। ये सुषुम्ना की गाँठ है।"]],[2344,["चलिए। अब इसको इस तरह से ले जाकर के,","ऊपर सर को घुमा के, इस तरह से"]],[2352,["एक बार पहले बाँधना, फिर दूसरे बार बाँधना","और फिर तीसरे बार इस तरफ खींच के","- जिसे नीर गाँठ कहते हैं।"]],[2362,["अब देखिए हाथ। ज़ोरों में शुरू हो गया मामला।","आप ही ने अपना काम किया।"]],[2382,["बिल्कुल साधारण। किसी भी चीज़ में जाने से","पहले बंधन ले लेना चाहिए।"]],[2388,["अगर किसी के सामने आप बंधन नहीं दे सकते","हाथ से, तो अपने चित्त से ही बंधन दे दिया।"]],[2394,["चित्त से बंधन दें। बंधन बहुत ज़रूरी है। उससे","कोई सी भी आसुरी विद्या या कोई सी भी","गलत चीज़,"]],[2402,["आपके अंदर नहीं घुस सकती। आप ज़्यादा","प्रभावित होकर के उस इंसान को, उस घटना","को, या उस स्थिति को लाँघ लेते हैं।"]],[2412,["उत्तेजित होने की बिल्कुल कोई ज़रुरत नहीं।","सहज में ही, आपको आश्चर्य होगा, कैसे काम","बनते जाएँगे।"]],[2420,["परमात्मा के दूत इतने सुन्दर हैं, आपके हर","एक काम को बना देंगे।"]],[2427,["लेकिन ये बस सोचना, अभी तक हमने कुछ पाया","नहीं है, और ये करके देखिए इसमें कितना","लाभ होता है।"]],[2438,["ये एक तरीका आपका बाह्य में हो गया। अब हमारे","यहाँ आगे चल के लोग बहुत कुछ करते हैं,"]],[2450,["लेकिन शुरुआत में जैसे मैंने आपसे ध्यान की विधि","बताई, ऐसे दोनों मर्तबा, एक रात को दस मिनिट"]],[2456,["और सवेरे पाँच मिनिट ध्यान करने का।","ज़्यादा कोई करने का नहीं।"]],[2461,["और किसी भी चीज़ की ओर जब आप देखें,","तो कोशिश करें कि निर्विचार हो जाएँ।"]],[2466,["ये स्थिति बढ़ाती जानी चाहिए निर्विचारिता की","- ये बहुत ज़रूरी है।"]],[2471,["निर्विचारिता की स्थिति जब तक आप बढ़ाएँगे","नहीं, तब तक आपकी वृद्धि नहीं हो सकती।"]],[2479,["जब चल-विचल माइंड रहेगा, मन चल-विचल","रहेगा - जैसे पृथ्वी अगर चल-विचल हो जाये"]],[2486,["तो इसमें कोई भी सृष्टि नहीं हो सकती। इसी","प्रकार जो मन चल-विचल हो जाता है,"]],[2490,["उसमें सृष्टि भी नहीं हो सकती, वृद्धि भी नहीं हो","सकती। इसलिए ध्यान घर में करना ज़रूरी है।"]],[2496,["पर इसके अलावा एक बात और है बहुत ज़रूरी","कि सहज योग एक सामूहिक चेतना का कार्य है।"]],[2507,["\"मैं माँ अपने घर में करता हूँ,\" सो नहीं।","जहाँ भी सेण्टर हो, एक हफ्ते में"]],[2516,["जैसे कि जाना अत्यंत आवश्यक है, इस तरह","वहाँ जाना ही चाहिए।"]],[2521,["वहाँ हमारा चित्त होता है, जहाँ दस सहज योगी","बैठ कर के ध्यान करते हैं।"]],[2526,["इसलिए आपको ज़रूर आना चाहिए। और वहाँ","रह कर के, वहाँ पर शुरू में आप देखिएगा"]],[2533,["राजकारण शुरू होगा क्योंकि हम लोग अधोगति","का एक रास्ता है, ऊर्ध्वगति का एक रास्ता है।"]],[2538,["ऊर्ध्वगति के रास्ते से अधोगति पे थोड़े से आ","जाएँगे, फिर इधर कूदेंगे - बन्दर कूदी","होती रहती है।"]],[2542,["शुरुआत में होगा ऐसे आप देखिएगा। फिर आप","देखेंगे एक साहब हैं, वो ज़्यादा ही कुछ करेंगे"]],[2546,["कोई दूसरा ही उसकी गर्दन खींचेगा। ये अपने देश","की जो प्रथाएं है, वो थोड़ी बहुत खीचेंगीं आपके","हाथ पैर। कोई बात नहीं।"]],[2553,["संसार के भाग के सहज योग नहीं प्राप्त","करने का है - यहीं रह के करने का है।"]],[2557,["इसलिए जो कुछ भी उथल-पुथल हो उसे","देखते रहे साक्षी स्वरुप हो कर के।"]],[2561,["और चीज़ बनती जाएगी। धीरे-धीरे आपको आश्चर्य","होगा कि जो लोग प्रगति करेंगे जो लोग ऊँचे","उठ जाएंगे"]],[2569,["वही इसका संचालन करेंगे और संभालेंगे।"]],[2573,["तो सबसे पहले हमारी उँगलियाँ जो हैं, वो पूर्णतया","संवेदनशील, माने सेंसिटिव होनी चाहिए।"]],[2580,["ये सबसे पहली चीज़ है। अगर उँगलियाँ अभी","संवेदनशील नहीं हैं, तो उसका इलाज","करना चाहिए।"]],[2587,["एक चीज़ हमारे यहाँ कुमकुम का बहुत","महत्त्व होता है - इस कुमकुम।"]],[2591,["तिलक हम लोग पहले लगते थे। तो रात में सोने","से पहले - आप लोगों को हम कुमकुम दे देंगे"]],[2598,["वो लगा के आप सोईए, सवेरे मुँह धो लीजिए।","रात में लगा के सोना चाहिए।"]],[2603,["उसी प्रकार शारीरिक व्यथा के लिए भी, कोई","चीज़ें हम मन्त्रित करके जिसे कहते हैं,","माने जागृत करके,"]],[2612,["वाई विब्रेट करके रख जाएंगे। जैसे पानी है,","इसी प्रकार शक्कर है और नमक है, कुछ तेल हैं।"]],[2626,["ये हम यहाँ मन्त्रित करके रख जाएंगे,","वो आप इन लोगों से ले जाईए।"]],[2630,["आप घर से लेते आइयेगा और उसी में थोड़ा","सा डलवा के ले जाइए।"]],[2634,["उसको बढ़ा दें, उसको बढ़ाते रहें और लेते रहें।"]],[2638,["अब कुछ लोग हैं जिनको लिवर की शिकायत है,","उनके लिए भी छोटी-मोटी बातें बता देंगे"]],[2644,["जिससे लिवर ठीक हो जायेगा। किसी को कोई","और शिकायत है, वो ये लोग सब समझते हैं,","ये आपको बता देंगे।"]],[2650,["तो ये कोई आपके गुरु नहीं हैं, लेकिन जैसे","कि सीनियर लोग हैं।"]],[2655,["तो इनसे सीखने में बुरा नहीं मानना चाहिए।","शायद हो उमर में आपसे छोटे हों, चाहे","बड़े हों, फर्क नहीं पड़ता।"]],[2665,["इसलिए हमें सीखना है अभी, ये सोचना चाहिए।","अभी शुरुआत हुई है। अभी आप, अभी-अभी","आप परमात्मा के दरबार में आए हैं।"]],[2674,["इसके कायदे-कानून थोड़े सीखने पड़ेंगे, ये समझ","लेना है; बस यही सीखना हैं और क्या है।"]],[2686,["आप लोगों में से ऐसे भी कोई हैं जिनके हाथ","में अभी ठंडक नहीं आई?"]],[2691,["नहीं आई हो तो बता दीजिए, ये लोग ठीक","कर देंगे। हैं अभी?"]],[2697,["अभी जिसको नहीं आई हाथ ऊपर करें।","अभी भी नहीं आई? अच्छा अब ऐसे हाथ रखें।"]],[2705,["आप जिस परमात्मा को मानते हैं - समझ लीजिए","आप श्री कृष्ण को मानते हों"]],[2711,["या शक्ति को मानते हैं, जिसको भी मानते हैं,","पूछिए कि, \"माँ, स्वयं साक्षात आप ही वे हैं?\""]],[2721,["शक्ति तो एक ही होती है, इतना पूछिए आप।","आँख खोल के पूछिए डंके की चोट पर -","हमें तो डर नहीं, आप पूछिए।"]],[2727,["हम्म! तीन बार पूछिए। बेटे, जिसको आप मानते हैं,","पूछिए कि, \"माँ क्या साक्षात आप वही हैं?\""]],[2744,["पूछो। हम्म! मन में पूछिए। मन में पूछिए।","हाथ में एकदम ठंडक आ जाएगी।"]],[2757,["आँख खोल के पूछिए।"]],[2769,["आई?","साधक: उष्णता आ गई।","श्री माताजी: उष्णता आ रही।"]],[2774,["उष्णता चली जाएगी। लिवर से होता है, उष्णता","आ रही है। कोई बात नहीं ऐसे हाथ कर लीजिए।"]],[2778,["जिनके उष्णता आ रही, राइट हैंड","हमारे ओर करें, लेफ्ट हैंड ऐसे कर लें।"]],[2782,["आपको उष्णता आ रही? कौन से हाथ में?","गर्मी आ रही? नहीं आ रही, तो फिर क्यों","ऊपर कर रहे हैं?"]],[2788,["आप नाम लीजिए। अब जो लोग सिगरेट पीते हैं,","तम्बाकू खाते हैं - वो हम कहते नहीं, मना नहीं","करते - अपने आप ही छूट जाएगा।"]],[2799,["लेकिन उससे विशुद्धि चक्र पकड़ जाता है, इसलिए","हाथ में महसूस नहीं होगा पर सर में ज़रूर होगी।"]],[2805,["(सहज योगियों से) अच्छा ज़रा देखिए।","ज़रा देखिए और पता लगाइये।"]],[2807,["अभी ये परदेस से लोग लाये हैं योगी लोग।","अभी आप को परदेस जाना है।"]],[2812,["ज़रा देखिए। आप हाथ उठाइए जिनको आ","नहीं रही। आ रही है, तब तो देखिए।"]],[2817,["अभी भी नहीं आ रही? आप किसको मानते हैं?"]],[2819,["सहज योगी: जिस जिस को नहीं आ रही, वो","ज़रा हाथ खड़ा करे ताकि वो पीछे से आ के ...."]],[2822,["श्री माताजी: ऐं?","सहज योगी: एक-एक हाथ खड़ा कीजिए।"]],[2825,["श्री माताजी: श्री कृष्ण को? अच्छा! पूछिए, \"माँ आप","साक्षात्,\" - यहाँ बैठिए। पूछिए, \"माँ, आप साक्षात्","श्री कृष्ण हैं?\""]],[2840,["ये कहीं से आये हैं? ऐं? आप यहाँ पर्यटक थे?","अच्छा! क्या आपने इन्हें आत्मसाक्षात्कार दिया है?","बहुत अच्छा!"]],[2852,["देखिए ये लोग पार हो गए। हाँ, इनको देखिए।"]],[2856,["हाँ! श्री कृष्ण को मानते हैं? कोई गुरु-शुरु रहे","होंगे? गुरु तत्व ख़राब हो गया है, गुरु गड़बड़ है।"]],[2866,["आप इधर ये हाथ रखें। पेट पर। ना, ना, राइट","हैंड। इधर पेट पर रखिए, अंदर। अंदर।","खोल लीजिए ज़रा। हम्म!"]],[2874,["पेट पे रखिए। अब ये हाथ मेरी ओर करके","कहिए, \"माँ, मैं ही स्वयं का गुरु हूँ।\" कहिए"]],[2881,["हाँ। पानी और दीजिए, डॉक्टर साहब।","बहुत गर्मी हो रही। हम्म, शुक्रिया।"]],[2902,["ये हाथ मेरे ओर करो, बेटे।","सहज योगी : ये हाथ इस तरफ कीजिए।"]],[2905,["श्री माताजी: माँ के तरफ।","सहज योगी: एक हाथ माँ की तरफ रखिए, दूसरा ..."]],[2908,["श्री माताजी: हाँ! ये गुरुओं के चक्कर भी बहुत","भयंकर होते हैं। ये डॉक्टर साहब ने बताया","होगा आपको।"]],[2923,["सहज योगी: महसूस हो रहा है? दूसरे हाथ से","देखिए। ये हाथ नीचे कीजिए। इस तरफ","हाथ रखिए दूसरा।"]],[2933,["अपना ध्यान यहाँ पर रखिए। थोड़ा हाथ ऊपर","करिए। बिल्कुल शीतल प्रवाह .... दोनों हाथ","सामने करिए।"]],[2947,["श्री माताजी: वो दे रहे हाथ पार कराने। जरा","इन सज्जन को देखिए। उनसे बात करो।"]],[2965,["वे किस देश से हैं?","सहज योगी : माँ ये दोनों काठमांडु से आ रहे हैं।","वे सेंट (अस्पष्ट) जाएंगे।"]],[2972,["श्री माताजी: मैं समझ गई। यही तो मैं सोच रही थी।","सहज योगी : ये दोनों जर्मनी से हैं।"]],[2978,["श्री माताजी: अच्छा! आपको जर्मनी में बहुत","कुछ करना होगा, मुझे कहना होगा।"]],[2992,["क्या हाल?","सहज योगी: बायाँ स्वाधिष्ठान।"]],[2998,["श्री माताजी: आप कहिए, \"माँ मुझे शुद्ध","विद्या दीजिए।\" बस। आपको भी वही शिकायत है?"]],[3010,["सहज योगी: उनको तो महसूस हो रही है।","श्री माताजी: ऐं?"]],[3012,["सहज योगी: उनको तो महसूस हो रही।","श्री माताजी: अच्छा! हिंदी जानते हैं क्या?"]],[3027,["आप हो गए पार? इनको सिखाओ इनको।","ज़रा सिखाओ इनको।"]],[3033,["अरे, आपको यह काम राजस्थानियों से","करवाना चाहिए।"]],[3037,["लेफ्ट स्वाधिष्ठान का बहुत ज़ोर है।","बाप रे बाप! कौन गुरु हैं आपके? ऐं?"]],[3046,["वेदांत्री? ऐं?","सहज योगी: अयोध्या के कोई वेदांती हैं।"]],[3058,["श्री माताजी: वेदात्री?","सहज योगी: वेदांती।"]],[3060,["श्री माताजी: वेदांती। हो गया।"]],[3071,["सहज योगी: खाते हैं? खाते हो? इसीलिए ये","पकड़ा हुआ है, तभी महसूस नहीं हो रही है।"]],[3076,["श्री माताजी: क्या, क्या खाते हैं? तम्बाकू?","कोई बात नहीं छूट जायेगा सब।"]],[3081,["सहज योगी: ठीक हो जाएगा पर ये इसी वजह","से आपका ये ज़्यादा है।"]],[3085,["श्री माताजी: इनको 'अल्लाह हो अकबर'","करने को कहिए। थोड़ा मुसलमान हो जाओ"]],[3087,["चलो कान में ऊँगली डालो। हम्म, बोलिए।","इनको कहिए। ये भी मन्त्र है विराट का।"]],[3091,["अकबर माने विराट। मोहम्मद साहब ने विराट की","बात की थी सारी। मुसलमान भी नहीं समझते","और हिन्दू भी नहीं समझते बात को।"]],[3101,["सहज योगी: ऊपर करके और कहिए, सोलह","मर्तबा कहिए, ईश्वर महान हैं - एक हैं।","'अल्लाह हो अकबर'"]],[3107,["सोलह दफ़ा कहिए।","श्री माताजी: सोलह दफ़ा कहिए।"]],[3115,["सहज योगी: प्रेम से कहिए, सोलह दफ़ा कहिए।","श्री माताजी: अब आप सीख लीजिए साहब।","ये तो बड़ी ज़ोर के पार हुए हैं - ये।"]],[3122,["सहज योगी: कौन?","श्री माताजी: ये जो बीच में बैठे हैं महाशय।"]],[3125,["सहज योगी : हाथ रखिए सामने आनंद लीजिए।","श्री माताजी: आँख की फरक आता है। आँख में","फर्क आता है।"]],[3129,["एकदम आँख में चमक आ जाती है। आप भी।","एक चमक आ जाती है आँख में।"]],[3134,["ये हुए उधर में वो एक बैठे हैं।","सहज योगी: चेहरा ही बदल जाता है।"]],[3143,["श्री माताजी: ऐं?","सहज योगी: चेहरा ही बदल जाता है।"]],[3144,["श्री माताजी: चेहरा बदल जाता है। एक मुस्कराहट","आ जाती है वो कुछ।"]],[3148,["श्री माताजी: ऐ?","साधक: मेरे लिए क्या हो रहा है?"]],[3151,["श्री माताजी: अभी वो पीछे देख रहे हैं ना बैठे","हुए। क्यों परेशान हो रहे हो बेटा?"]],[3154,["ज़रा सी घबराओ नहीं। तुम्हारे लिए ही तो","मेहनत कर रहे हैं पीछे बैठे हुए।"]],[3158,["हो जाएगा, हो जाएगा - कोई चिंता नहीं करो।","आओ इधर आओ।"]],[3163,["ये तो बिल्कुल ही छोटे बच्चे हैं। आइए।","आओ, आओ बैठो, बैठो। क्या नाम तुम्हारा?"]],[3168,["साधक: श्यामलाल।","श्री माताजी: ऐ?","साधक: श्यामलाल।"]],[3170,["श्री माताजी: श्यामलाल। बैठो श्यामलाल, बैठो।","क्या बात है! बैठो, बात करो।"]],[3174,["साधक: मुझे तो गर्मी महसूस हो रही है।","श्री माताजी: हाँ वो तो बात है। दोनों हाथ में?"]],[3177,["वो ही तो बात है। वो ही तो हो रहा है तुम्हारा।","ज़रा गर्मी निकलने दो फिर ठंडक आएगी।"]],[3188,["आप किसको मानते हो ? श्यामजी को?","साधक: श्री राम।"]],[3191,["श्री माताजी: श्री राम। चलो भाई, अब पूछो","सवाल। ये लेफ्ट हैंड ऐसे करो। हम्म।"]],[3198,["अब पूछो, \"माँ आप ही साक्षात् श्री सीता राम","हो क्या?\" पूछो। आँख खोल के, आँख नहीं","बन्द करना।"]],[3205,["ऊपर चित्त नहीं चढ़ाओ बिल्कुल। सीधे सवाल","मेरे मुँह को देख कर पूछो। हम्म।"]],[3230,["श्री राम। आप मत कीजिए। आप - दायाँ हृदय।"]],[3235,["सहज योगी: माँ, यह वही हैं जो प्रश्न पूछ रहे हैं,","\"क्या मैं भगवान का नाम ले सकता हूँ, माँ","का नाम नहीं।\""]],[3243,["श्री माताजी: एक और - वो जो सीताजी को","निकाल दिया था उनमें से तो नहीं हो तुम?"]],[3253,["साधक: क्या अर्थ है, समझा नहीं ?"]],[3256,["श्री माताजी: वो कह रहे हैं कि इन्होंने ये कहा कि","बाप का नाम क्यों न लिया जाये, माँ का","क्यों लिया जाए?"]],[3261,["तो वो ही सीताजी को निकाला था ना लोगों ने,","उसका अभी तक पाप भोग रहे हैं यू.पी.","वाले और भोगेंगे।"]],[3273,["महालक्ष्मी स्वरूपा उस सीता को घर से निकाल","दिया - माँ के बगैर घर की शोभा क्या है?"]],[3291,["उसी लिए उनसे कह दिया - राइट हार्ट उनका भी","पकड़ता था। अब बस आप दाएँ ह्रदय पर","प्रयास मत करना।"]],[3299,["हाँ, अब देखो, आ रही?","साधक: सीधे हाथ में।"]],[3304,["श्री माताजी: आ रही है ना। अब ज़रा सीताजी से","क्षमा माँग लो कि तुम्हारा जब अपमान हुआ था"]],[3313,["तो हम खड़े देखते रह गए - कुछ कहा नहीं,","अयोध्या जी में। हाँ!"]],[3328,["आया, मामला हाथ में? अब ये भी लाओ,","इधर रखो।"]],[3337,["अरे, हनुमानजी भी रामचंद्र जी से लड़ पड़े थे","सीताजी के लिए।"]],[3344,["साधक: किस दिन?","श्री माताजी: काफी समय पर।"]],[3351,["और सीताजी ने भी रामचंद्र जी का त्याग किया","था सीधे समय पर, स्त्री की तरह से।"]],[3359,["त्याग क्यों नहीं किया? पृथ्वी में नहीं समा गईं?","वो गईं क्या उनके साथ, फिर?"]],[3366,["फिर रोते फिरे उनके लिए 'सीता, सीता'","कहते हुए और सरयू में समाधि ले ली।"]],[3373,["सीता के बगैर राम भी क्या हुए ? सीता का नाम","पहले लिया जाता है, फिर रामचंद्रजी का। हाँ!"]],[3383,["और अगर सीताजी कुछ नहीं थीं, तो उसके","पीछे क्यों गए थे ढूँढने के लिए?"]],[3392,["हाँ! स्त्री और पुरुष का अंतर जो है मनुष्य","समझता है, परमात्मा नहीं।"]],[3402,["चंद्र और चन्द्रमा, चन्द्रिका, इसका कोई अर्थ","अलग नहीं लग सकता। शब्द और अर्थ","कैसे एक साथ रहते हैं?"]],[3411,["उसी तरह से परमात्मा और उनकी शक्ति","साथ-साथ चलती है। फर्क तो इंसान अपनी","बुद्धि से करता है।"]],[3418,["अब जब शिव और कृष्ण का भी झगड़ा लगाए","हुए हैं।"]],[3425,["वो भृगु मुनि थे, उन्होंने यही झगड़ा खड़ा किया","था, तो अर्धनारीनटेश्वर बन गए शिव। लेकिन","समझ में नहीं आता है ना हमारे।"]],[3439,["हाँ! देखो, उठाओ। और सीताजी के जाने के बाद","घास पर क्यों सोते थे श्रीरामचन्द्रजी?"]],[3455,["जिनको मानते हो उन्हीं से सीखो भाई। समझ गए?"]],[3471,["साधक: कुछ (अस्पष्ट)","श्री माताजी: ऐं?"]],[3473,["साधक: कुछ होता है बाएं हाथ में।","श्री माताजी: अभी बाएं में है। चली जाएगी,","चली जाएगी।"]],[3478,["ये राइट हैंड पृथ्वी पर रखो - ये सीता की माँ है।"]],[3491,["सहज योगी: माँ, कल रात से शोर सुनाई दे रहा है","और (अस्पष्ट) ..."]],[3499,["श्री माताजी: वह कुछ गुरुओं के पास गए हैं। उनसे","कहो कि वह अपना दाहिना हाथ अपनी बाईं","नाभि पर रखें और कहें कि"]],[3514,["हैं बेटे? है तकलीफ़? वो चली जाएगी।आइये।"]],[3523,["अब बोलिए ठंडक जा रही? ये ही है ना उसकी","माँ जो तुम्हारा सब खींच रही दुःख।"]],[3528,["बुलाओ श्री राम को। हाँ!"]],[3542,["एक आश्चर्य होता है कि श्री राम को भजने वाले","सीता जी का उनका प्यार क्यों नहीं समझ पाते?"]],[3553,["कृष्ण को भजने वाले राधा को समझते हैं,","पर सीताजी को कोई नहीं पहचान पाता।"]],[3560,["वो ही चीज़ है - हो गए। हो गए? ठंडक","तो आ रही। हो गया ना?"]],[3581,["मामला बन गया? इनके सिर पर देखिए।","ऑंख बन्द कर लो।"]],[3590,["आँख बन्द करो, आँख सीधे बन्द करो।","ऐसे ऊपर नहीं चढ़ानी, सीधे।"]],[3593,["नहीं नहीं इस तरह से नहीं, सीधे आँख जैसे बन्द","करते हैं हम, ऐसे बन्द - ना, ना, ना।"]],[3598,["मेरे पैर के ओर देख के बंद करो, चलो। नीचे","देख, नीचे देखते रहो। तुम फिर चढ़ा लेते हो आँखें?"]],[3603,["ऊपर चढ़ाने की कौन सी मतलब है। नीचे ऐसे","सादे, जैसे हम बंद कर लेते हैं साधे, उस तरह","से बंद करिए आप।"]],[3610,["ऐसे ऊपर चढ़ाने की ज़रुरत क्या?","हाँ ऐसे शांत चित्त।"]],[3632,["हाँ, आपका क्या हाल है? इनसे कहिए - (वारेन से)"]],[3637,["वॉरेन आप उसकी विशुद्धि ठीक करें।","उन्हें बस यही चाहिए।"]],[3640,["अब तम्बाकू तो छूट जाएगी मैं क्या करूँ। हम","लोग सब गणपतिपुले गए थे, वहाँ सब दुकानदारों","की मौज हो गई।"]],[3649,["सिवाय बेचारे पान, बीड़ी, माचिस वाले","की हालत ख़राब हुई।"]],[3653,["उसने कहा, \"मेरा तो एक भी चीज़ नहीं बिकी;","माचिस तक किसी ने खरीदी नहीं।\""]],[3664,["श्री माताजी: बस उन्हें उनकी देखिए - उनकी","विशुद्धि को ठीक करिए।"]],[3666,["हाँ! यह दाएँ ह्रदय वाला व्यक्ति है, पक्का","दाएँ ह्रदय वाला ये है।"]],[3675,["ऐं? ये भी? किसके भगत हो? हनुमानजी के?","हाँ फिर, ऐं ? कौन सा जप है?"]],[3696,["हाँ, पर कौन है भई?","सहज योगी: मन्त्र दिया हुआ है? काहे का मन्त्र?"]],[3707,["श्री माताजी: दायाँ ह्रदय - तभी पकड़ आ रही।","हाँ! बोलो मन्त्र मेरे सामने - और ये हाथ","ज़मीन पे रखो।"]],[3717,["हाँ, बोलो। मन्त्र बोलो। ये हाथ ऐसे करिए अब।","हाँ, अब बोलिए। ये पार हो गए।"]],[3750,["हम्म! नहीं? अच्छा ये हाथ इधर करो। इधर","- अब राइट हैंड ज़मीन करिए पे रखो, अब बोलो।"]],[3760,["बाईं, दाईं - दोनों विशुद्धि। किसी को बुलाओ।","इनको प्राप्त हो गया है, ज़रा देखिए इन्हें अब।","ये वाले, ये वाले।"]],[3770,["दायाँ ह्रदय। अब आप अच्छे हैं?","दायाँ ह्रदय अब नहीं पकड़ते।"]],[3785,["लेकिन आप देखिए, कमज़ोरी कैसे कमज़ोरी","की ओर जाती है। यही तो बात है"]],[3792,["साधक : माँ, मेरा नहीं हुआ।","श्री माताजी: नहीं हुआ? अच्छा अभी देखते हैं।"]],[3796,["आपका हुआ नहीं? पार हुए कि नहीं हुए? हो गए?","रखो, रखो और फिर हाथ हाथ काहे बाँध के रखे हो","जब माँ के सामने बैठे हो तुम?"]],[3804,["आपका हुआ बेटा?","साधक: गरम हो गया।"]],[3807,["श्री माताजी: दोनों हाथ में? अच्छा। राइट हैंड","ऐसे रखो, लेफ्ट हैंड ऐसे रखो।"]],[3816,["ज़रा दूर-दूर बैठो, पास-पास नहीं। चित्त यहाँ","रखना, चित्त यहाँ रखो बेटा।","साधक: आपके चरणों में बताया आपने।"]],[3825,["श्री माताजी: अब तो यहाँ रखो चित्त। नहीं, नहीं","आँख नहीं उठाना बस - आँख तो चरणों में","ही रखो बस।"]],[3830,["आँख चरणों में रखो, चित्त को यहाँ रखो। चित्त","माने ध्यान। हाँ अब कहो, \"श्री माताजी मेरे","सर में आइये,\" कहो।"]],[3844,["\"कृपया मेरे सर में आइए।\" लिवर - लिवर बहुत","ख़राब है, इनके लिवर है। इनके लेफ्ट से","राइट में डालिये।"]],[3859,["हाँ! लग रहा है सर में कुछ आया क्या?","साधक: हाँ, इससे ठंडक आई।"]],[3864,["श्री माताजी: आई? देखो अब, आप अपने हाथ से","देखो। ज़रा ऊपर उठाओ बेटा, ऊपर। आ रही?"]],[3874,["साधक: हाँ कुछ महसूस हुआ। उस समय","हुआ जब आपने हाथ ...."]],[3876,["श्री माताजी: अच्छा, अभी देखो, अभी होएगी।","कहते रहो, \"माँ,\" ह्रदय से कहो,"]],[3885,["अपने अंदर ही कहो, \"माँ मेरे सर में आइए\""]],[3892,["फिर से। सात बार कहना। हाँ ! आपको बेटा?","चश्मा उतार लो ज़रा, चश्मा उतार लो।","देखें - चश्मा उतार लो।"]],[3914,["आगे आओ, आगे, थोड़ा आगे आ जाओ।","तुम्हारा आज्ञा घुमायें। थोड़ा आगे आ जाओ बेटा।"]],[3919,["आगे सरक जाइए, ज़रा से। ढीला छोड़ो, ढीला","छोड़ो, ढीला छोड़ के बैठो। माँ के सामने बैठे हैं।"]],[3926,["अच्छा दोनों हाथ ऐसे रखो, चलो दोनों हाथ इस","तरह से। हाँ आँख बंद कर लो। आज्ञा की पकड़","ज़रा ज़बरदस्त है इनकी।"]],[3938,["वॉरेन, अगर आप एक मोमबत्ती ला सकें।","इस सज्जन की पिछली आग्या खराब है।"]],[3946,["इनका क्या हाल है? कुछ नहीं बन रहा? नहीं","आया? इधर आ जाओ, इधर। आपका क्या हुआ?"]],[3954,["आप बैठे रहो, बैठे रहो, वो देख रहे। मैं इनको बोल","रही। आपका क्या हुआ? आपको पूछ रही।"]],[3960,["हाथ में नहीं आ रही? कठिन जीव हो तुम। कल","सबकी मेहनत बेकार हुई।","अब कुछ अपनी भी मेहनत करो दो-चार रोज़।"]],[3973,["ऐं?","साधक: मैं तो समझो यहाँ नहीं हूँ, इनके घर","मैं हम लोग हैं।"]],[3977,["श्री माताजी: अच्छा! उनकी लड़की है?","साधक: बहू","श्री माताजी: बहूजी हैं, अच्छा।"]],[3986,["सहज योगी: इनको हाथों में महसूस नहीं हो रहा।","श्री माताजी: विशुद्धि की पकड़ है बहुत ज़ोर की।"]],[3992,["लिवर भी है। डॉक्टर साहब, लेफ्ट से राइट","करिए, देखिये अभी हो जायेगा।"]],[3995,["हाँ रहन दो। दोनों हाथ रखो मेरी ओर, दोनों हाथ।","सहज योगिनी: इसको तो आ गई है।"]],[4002,["श्री माताजी: इनको आ गई। बच्चे हैं ना अभी,","इधर-उधर उलझे नहीं।"]],[4009,["ये गुरुओं के चक्करों में उलझ गए फिर","उसके बाद बड़ा मुश्किल हो जाता है।"]],[4019,["हम्म, ठीक है?","साधक: आपके हाथ रखने से ठंडक होती है।"]],[4023,["श्री माताजी: तुमको चाहिए कि मेरा ही हाथ","रखा रहे। आ जाएगा, देख लेंगे, देख लेंगे।"]],[4028,["अब आ नहीं रही ठंडक? चित्त यहाँ रखो, यहाँ।","ज़रा बाँधो इनकी कुण्डलिनी, कौन है?","इनकी बाँधिए ज़रा।"]],[4040,["आप आइए, ऐसे बैठ जाइए। घास में बैठिये,","बाँध देंगे आपकी। बांधना सीखिए।"]],[4046,["साधक: बाहर जाऊँ?","श्री माताजी: नहीं यहाँ, उधर, बैठा रहे।"]],[4048,["देखिए ऐसा है कुण्डलिनी गिर जाती है। उसको","फिर चढ़ा के बाँध देंगे। उठिये, बैठिये, आपको","समझा भी देंगे बाँधना कैसे है।"]],[4055,["कुछ नहीं हुआ? अभी हो जायेगा।","साधक: मैं पतित हूँ क्या जो मेरे को कुछ नहीं","होता, क्या बात है?"]],[4063,["श्री माताजी: ज़रा मेरे पे विश्वास कम है।","साधक: अच्छा।"]],[4068,["श्री माताजी: है ना?","साधक: नहीं ऐसी बात तो नहीं है।"]],[4071,["यानी, जिज्ञासु हो के आपके पास आया हूँ -","मैंने कोई गुरु-वुरु नहीं किए।"]],[4074,["श्री माताजी: वो तो ठीक है। जिज्ञासु तो","हो के तुम आये हो बेटा,"]],[4077,["पर जिससे इतनी बड़ी चीज़ लेनी है, उस पर","थोड़ा विश्वास करना होगा।"]],[4080,["साधक: नहीं विश्वास तो मैं कर लूँ,","श्री माताजी: अच्छा"]],[4084,["साधक: नहीं ये नहीं है, अविश्वास नहीं कर","रहे आपकी बात पर"]],[4086,["श्री माताजी: अच्छा चलो, आओ, हो जायेगा","घबड़ाओ नहीं। अपने को बुरा नहीं समझो बस,"]],[4089,["सबसे बड़ी बात ये है। बुरा नहीं समझो बस।"]],[4091,["साधक: नहीं, तो जब औरों पर असर होता है,","मेरे पे क्यों नहीं होता?"]],[4093,["श्री माताजी: क्योंकि सहस्त्रार पे हमारा","स्थान है और सहस्त्रार पे ही रुक रही।"]],[4097,["तो इसका मतलब, हमारे प्रति जो है आपकी अभी","श्रद्धा थोड़ी बैठ जाएगी, बैठ जाओ, वो बाँध देंगे","तुमको - ज़बरदस्ती नहीं बैठी।"]],[4103,["हम्म अब क्या हाल?","साधक: अभी यहाँ तो महसूस होती, हाथों में","नहीं होती।"]],[4120,["श्री माताजी: किसको मानते हैं आप?","साधक: गणेश को।"]],[4123,["श्री माताजी: तो तो बहुत आसान है। सवाल पूछिए,","\"माँ आप श्री गणेश हैं, श्री गणेश गौरी हैं","आप माँ?\""]],[4135,["बेटे आपके नहीं हो रहा? ये लेफ्ट स्वाधिष्ठान","पे देखो। बहुत ज़ोर का।"]],[4143,["तुम्हारे कोई गुरु-वुरु हैं? गुरु हैं? फिर उसी","से तो हो गया। गड़बड़ काम है गुरु का।"]],[4162,["अच्छा यहाँ बैठो ज़रा, इधर ज़मीन पर।","इनको ऐसा करो इनको एक दीप -"]],[4167,["दोनों जने, दोनों बैठिये। आप भी।","इनके गुरु हैं, ज़मीन पर बैठिये।"]],[4175,["साधक: इधर, इधर मुँह कर लें माताजी के सामने।","श्री माताजी: हाँ, मेरी - बैठिए।"]],[4177,["थोड़ी देर ध्यान कर लें हो जायेगा। \"माँ मेरे","सर में आइए। माँ मेरे हाथ में आ जाइए,\"","कहना पड़ेगा।"]],[4185,["नहीं, मैं कर दे रही हूँ। क्या हुआ इनका?","नहीं बन रहा? ऐं? हाँ, क्या बात?"]],[4205,["साधक: मुझे फीलिंग्स नहीं आ रहीं। जैसे होना","चाहिए उस हिसाब से नहीं हो रही। क्या कारण है?"]],[4210,["श्री माताजी: बताओ। कारण नहीं बताएँगे हम,","आपको फीलिंग करा देंगे। कारण क्यों बताएँ?","अच्छा वो हाथ की अंगूठी ..."]],[4215,["साधक: वाईब्रेशन हमको महसूस होता है, जब","कुण्डलिनी (अस्पष्ट) वो हम महसूस कर रहा है","लेकिन (अस्पष्ट) नहीं हो रहा इसका मतलब"]],[4222,["श्री माताजी: अच्छा आप अंगूठी उतार लो ज़रा एक","मिनिट - बेटा तुम ये अंगूठी उतार के देख लो"]],[4226,["दोनों उतार लो, दोनों उतार लो, दोनों, वो भी","उतार दो, हम्म एक मिनिट;"]],[4230,["ज़रा उँगलयों पे बंधन आ जाता है","अंगूठियों से। हैं! चलो, ल्यो ऐसे रखो।"]],[4239,["आई बेटा? आज्ञा पर - सिंदूर है।"]],[4251,["क्या हाल है अब? सर में आ रही है?","सर में भी नहीं? हाथ में भी नहीं?"]],[4259,["अंगूठी उतारो, अंगूठी। लेफ्ट हार्ट पकड़","रहा है इनका। घड़ी भी उतार दो।"]],[4269,["बेटे तुम्हारी ये तो चमक गईं उंगलियाँ।","आना चाहिए। आज्ञा पर (अस्पष्ट)।"]],[4273,["साधक: (अस्पष्ट - दिल?) में चेंजेस आना चाहिए।","हम प्रैक्टिस करेगा हम ऐसे नहीं करेगा।"]],[4277,["हम डेली प्रैक्टिस करेगा लेकिन चेंजेस आना","चाहिए।"]],[4279,["श्री माताजी: हाँ, आ जायेगा, आ जाएँगे नहीं तो","क्या? आना तो चाहिए। होता ही है। हार्ट पकड़","रहा है। ज़रा एक मिनिट।"]],[4286,["साधक: ओवर कॉन्फिडेंस से तो हमारा हो नहीं","पाता है।","श्री माताजी: ऐं? आज ही आये हो ना?"]],[4292,["साधक: नहीं, कल रात आये थे।","श्री माताजी: तो भई और ज़रा शांति से ले लो -","सबूरी चाहिए, सबूरी। सबूरी से हो जायेगा।"]],[4299,["ठीक है आपका? ये तो हँसने लग गए। देखो अब ये","हो गए तो हँसने लग गए। तुमको हम कहते हैं,","सबूरी रखो, सबूरी रखें।"]],[4307,["आओ बैठो। हाँ? क्या हाल है आपका?","साधक: पता नहीं"]],[4315,["श्री माताजी: तो कल तो हो गए तुम पार।","नहीं हुए, नहीं? अच्छा ठीक है।"]],[4321,["साधक: माताजी मेरे यहाँ पैरों में यहाँ (अस्पष्ट)।","डायबिटीज भी है मेरे को, ब्लड प्रेशर भी।"]],[4326,["श्री माताजी: डायबिटीज है? वो ही आपका लेफ्ट।","आपको बैठे-बैठे अभी ऐसा करना है"]],[4332,["राइट हैंड मेरे ओर करिए,","लेफ्ट हैंड ऐसे, ऐसे लेफ्ट हैंड।"]],[4336,["आप नौकरी क्या करते हैं?","साधक: माताजी मैं रिटायर हो गया।","मैं सर्विस करता था।"]],[4340,["श्री माताजी: गवर्नमेंट की?","साधक: नहीं प्राइवेट। गवर्नमेंट से तो रिटायर","हो गया था।"]],[4344,["श्री माताजी: गवर्नमेंट से हो? तो पूछो एक, \"माँ","आप सारी गवर्नमेंट की गवर्नमेंट हैं क्या?\""]],[4353,["तुम्हारा आज्ञा पकड़ रहा है।","सहज योगी: माताजी लेफ्ट स्वाधिष्ठान, विशुद्धि","(अस्पष्ट)"]],[4370,["श्री माताजी: (अस्पष्ट) रह चुके, ऐसे बैठो, ऐसे, ऐसे","यूँ, आकाश। बाप रे बाप, बहुत भरे भयंकर!"]],[4383,["गुरुओं का मामला है। अच्छा राइट टू द लेफ्ट।","राइट टू द लेफ्ट, गुरुओं के मामले में। राइट टू द"]],[4389,["वारेन को हँसी आ रही। आप लोगों के भी","गुरू थे। आप सब के भी गुरु थे।"]],[4398,["(अस्पष्ट) सुन रहे हैं आप? गुरुओं का","मामला चला हुआ है।"]],[4407,["आइए इधर सामने। इसको छोड़ो, इधर चित्त रखो।","आँख बंद करो। सामने आओ, सामने।"]],[4419,["और आगे सरको। और आगे, आगे आओ। हाँ, अब","यहाँ चित्त रखो, आँख बंद करो। चित्त को यहाँ","रखो।"]],[4439,["बैठ जाओ, बैठ जाओ। उसको इधर बिठाइए,","कहना और हमारे ओर हाथ करके बैठें।"]],[4449,["एक हाथ, लेफ्ट हैंड हमारी तरफ, राइट हैंड ज़मीन","पर और एक लाइट दे दीजिये उसके सामने।"]],[4455,["आप बंधन ले लीजिये पहले। बंधन आप ले करके","फिर। हम्म! चित्त यहाँ रखो, चित्त यहाँ।"]],[4471,["अब कहो, \"माँ मेरे सर में आइए।\"","साधक: \"माँ मेरे सर में आइए।\""]],[4475,["श्रीमाताजी: हाँ, फिर से, बार-बार, सात बार कहना।","नहीं बन रहा? हुआ, हो रहा है। चलने दो।","चलेगा, चलेगा। हो रहा है, होने दो।"]],[4488,["कहो, \"माँ मेरे सर में आइए।\" बाप रे बाप!","इनके सबके तो वो भी है न - सहस्त्रार?"]],[4528,["खिंचने लग गया। यहाँ चित्त रखो। हो गया - ऐं?","ये तुम्हारे पकड़ आ रही है - ये है हंसा चक्र।"]],[4542,["इसमें ये थोड़ा सा घी डालना चाहिए तब इनके","नाक ठीक होएंगे। कोई घी मँगा लीजिये थोड़ा।"]],[4550,["आपका ठीक है हाल?? नहीं? सर में आ रहा है?","विशुद्धि [मराठी]"]],[4573,["अब क्या हाल है? कुछ तो ठीक है।","साधक: फील हो रहा है लेकिन"]],[4578,["श्री माताजी: अभी एकदम से बेटे नहीं हो रहा ना","- आराम से, आराम से, सबूरी चाहिए"]],[4583,["सबूरी तो हमारी ख़तम हो जाती है तुम","लोगों को देख-देख के फिर। हाँ!"]],[4623,["डॉक्टर साहब ये जो लोग पार हो गए हैं, और जो","कुछ कहीं पहुँच गए हैं, उनके आप पते-वते","ले लीजिए"]],[4630,["सो आगे के लिए भी कॉरेस्पोंडेंस लोग यहाँ","आना चाहेंगे; सबके पते ले लेने से"]],[4635,["थोड़ा सा ये हो जाएगा ना, जिसको कहते हैं,","सम्बन्ध। सम्बन्ध हो जाना चाहिए।"]],[4641,["कल कोई चीज़ हो तो सबके पते होने चाहिए।","बहनजी के पास रखा देंगे।"]],[4647,["बैठो। बैठो, बैठो। हाँ! अब मामला ठीक है।","शांत हो गया? हाथ में आ रही ठंडक?"]],[4661,["तुम तो हाथ भी तो खोलते नहीं हो? हाथ तो खोलो।","सब को माफ़ करो पहले। इधर आओ।"]],[4666,["माफ़ किया सबको? सच कहो? मन से कहो, फिर","से कहो। आँख बन्द करके कहो, \"माँ, मैंने","सबको माफ़ कर दिया।\""]],[4675,["साधक: माँ, मैंने सबको माफ़ कर दिया।","श्री माताजी: फिर से।"]],[4677,["फिर से कहो। ह्रदय से कहो, तुम तो ऐसे ही कह","रहे हो। ह्रदय से कहो।"]],[4690,["सहज योगी: श्री माताजी आ गई।","श्री माताजी: कहाँ जाएँ? हो गए वो?"]],[4694,["हाँ! बाँध दो, बाँध दो, अच्छे से बाँधो। उनको बाँधना","सिखा दो; उनकी गिर जाती है कुण्डलिनी।"]],[4702,["ठीक है अब कुछ? नाक में थोड़ा वो डलवा लो।","तुम क्या लाये घी?","सहज योगिनी: ला रहे।"]],[4707,["श्री माताजी: ला रहे हैं। उससे हंसा पे तुम्हारे","पकड़ आ रही, इसलिए आँख जो है ना"]],[4710,["बंद नहीं हो रही - देखा ना, चरचरा रही,","उसमें आँख में डलवा लो।"]],[4716,["हो रहा है अभी? आपको इस वकत हो रहा है?","तो नहीं होगा, और क्या, ठीक हो गए।"]],[4724,["हाँ! आपका नहीं हुआ? आओ, चलो आओ।","वारेन, वह एक अच्छा व्यक्ति है। ज़रा उसे देखें,","उसे साक्षात्कार दें।"]],[4736,["सहज योगिनी: हाँ, इनको कुमकुम लगा के,","बंधन दिया।","श्री माताजी: अच्छा भाई, अच्छा।"]],[4743,["कितनी जल्दी से पार हो गयी यही उसका साक्षात।","अच्छी नहीं होती तो इतनी जल्दी पार ही","नहीं होती।"]],[4754,["गुनगुना है?","सहज योगिनी: ज़्यादा गरम है?"]],[4757,["श्री माताजी: ज़्यादा गरम है? इतना गरम नहीं,","हो जायेगा बस ठीक हो जायेगा।"]],[4763,["दोनों को घोल के, नाक में थोड़ा सा - किसी","को काम दे दीजिए ये।"]],[4768,["कि एक नाक में थोड़ा रुई से डलवा दें।","ये लीजिये रुई। ये रुई लीजिए।"]],[4776,["(मराठी)"]],[4783,["आप भी बेटे, जाओ डलवा लें, आप भी।","दोनों, तीनो के नाक में ज़रा घी डलवाइए -","जाइए, आपकी विशुद्धि ठीक।"]],[4790,["नहीं हो रहा? क्या बोल रहे ये लोग? बेटे जाओ,","नाक में घी डलवा के फिर आना। तुम्हारी","अंगूठी कहाँ गई? वो रखी।"]],[4798,["वॉरेन: लेकिन आपको उपचार करने की","ज़रूरत नहीं है।"]],[4801,["श्री माताजी: यही समस्या है।","वॉरेन: मानसिक उपचार।","श्री माताजी: हम्म, यही समस्या है।"]],[4805,["एकादश पकड़ रहा है।","सहज योगिनी : श्री माताजी गुरु की समस्या"]],[4809,["श्री माताजी: ऐं?","सहज योगिनी : आज्ञा पकड़ रही, गुरु है।"]],[4811,["श्री माताजी: [मराठी]"]],[4817,["गुरु कौन है?","सहज योगिनी: आप नाम बताइये?"]],[4820,["श्री माताजी: ऐं?","सहज योगिनी: योगानंद परमानन्द।","श्री माताजी:अरे राम राम। बला!"]],[4827,["बेटा कहाँ से कहाँ। उसको कैसे पकड़ा तुम लोगों","ने? न देखा, न जाना, बस उसको गुरु बना लिया?","छी, छी, छी,"]],[4838,["सहज योगी: लेकिन यह गरम है, ठंडा नहीं हो रहा।"]],[4842,["श्री माताजी: [मराठी]"]],[4851,["आप जाइए कर रहे हैं ठीक। उनका तो निकालते","निकालते भूत बहुत मुश्किल काम है।"]],[4857,["साधक: हमारे कोई गुरु-वुरु नहीं हैं (अस्पष्ट)","करना चाहते हैं (अस्पष्ट) कुछ नहीं है","ना कोई गुरु है"]],[4866,["श्री माताजी: अच्छा! अच्छा बेटे, ये हाथ हमारी","ओर करो, राइट हैंड और लेफ्ट हैंड ऐसे करो।"]],[4870,["कहना, \"माँ, सारे शास्त्रों का आधार आप ही","हैं क्या?\" बोलो"]],[4874,["कहो, \"माँ, सारे शास्त्रों का आधार आप ही हो","क्या?\" ऐसे दस बार बोलो।"]],[4882,["\"सारे विद्या का आधार आप ही हो क्या?\"","ऐसे दस बार बोलना सिर्फ।"]],[4899,["ऐं ?","साधक: मेरा मन नहीं लगता है (अस्पष्ट)"]],[4904,["श्रीमाताजी: अच्छा दोनों हाथ ऐसे","करके आप बैठिए, अभी हो जायेगा।"]],[4907,["हाँ क्यों, कहा दस मर्तबा? ठंडक आई?","आई ना, जवाब भी आ गया।"]],[4913,["अब देखो सर पे हाथ रखो। अब कहो,","\"माँ मेरे सर में आइए।\""]],[4917,["तुमने क्या पढ़ा बेटा?","साधक: क्या पढ़ना है, बता दीजिये आप?"]],[4921,["श्री माताजी: नहीं, क्या पढ़ा है तुमने?","साधक: मतलब, एजुकेशन?","श्री माताजी: एजुकेशन नहीं। बाकी, धर्म के बारे में।"]],[4928,["साधक: धर्म के बारे में कुछ ख़ास नहीं।","श्री माताजी: अच्छा हुआ।"]],[4930,["और, तुमने किसी को गुरु-वुरु नहीं माना?","किसी को नहीं माना? एजुकेशन क्या है?"]],[4936,["साधक: बी ए","श्री माताजी: बी ए किया है।"]],[4940,["साधक: गुरु तो नहीं माना लेकिन जो धर्म है","हमारा धर्म है वो ही मानते हैं।","श्री माताजी: कौन सा धर्म?"]],[4943,["साधक: जैन धर्म।","श्री माताजी: जैन धर्म।अच्छा!"]],[4945,["ऐसा करो राइट हैंड ज़मीन पे रखो और","पूछो, \"श्री महावीर जी आप ही हो क्या माँ?\" पूछो।"]],[4953,["\"श्री महावीर जी आप ही हो क्या?\" ऐसे पूछो","सवाल। \"माँ आप ही श्री महावीर जी हो क्या?\""]],[4976,["आ गया? ये अतिचेतित/प्रतिअहंकारी है, अत्यंत","अतिचेतित/प्रतिअहंकारी - अत्याधिक।"]],[4990,["वॉरेन! हाँ सच में। मुझे कभी-कभी आपसे","सहानुभूति होती है - लेकिन मेरे बारे में क्या?"]],[4997,["हाँ, क्या? पूछा? पूछो, \"क्या माँ आप ही","साक्षात् श्री महाबीर जी हैं?\""]],[5004,["हाँ, क्या? अब ठीक है हाल? चल रहा है?","सर में भी? आ गई ठंडक?"]],[5009,["सर में नहीं? अच्छा कहो, दोनों हाथ ऐसे रख","के, \"माँ मेरे सर में आइए?\""]],[5013,["कहो, \"माँ मेरे सर में आइए।\""]],[5037,["वॉरेन: ठंडा हो रहा है।","श्री माताजी: केवल आप ही जानते हैं कि","इसे कैसे प्रबंधित किया जाए"]],[5044,["आप के हो गया? वाह भाई वाह!","बगदान सही जगह पर चले गए हैं।"]],[5058,["तो ये ही कहो कि, \"माँ मेरे सर में आओ।\"","पहले कहो, प्रैक्टिकल ल्यो।"]],[5062,["हम्म। 'पढ़ी-पढ़ी पंडित मूरख भयो।'","साधक: विवेकानंद जी के (अस्पष्ट)"]],[5067,["श्री माताजी: अरे रे रे रा रा। विवेकानद जी तो","बस बोलते ही रहे।"]],[5072,["साधक: मतलब बस वो ही कह रहे","(अस्पष्ट) पढ़ा लिखा नहीं।","श्री माताजी: वही तो गलती होती है।"]],[5077,["थ्योरी ज़्यादा हो जाती है, प्रैक्टिकल फिर","चलता ही नहीं हाथ हमारा।"]],[5084,["बिल्कुल सही जगह पर गए हैं। नहीं, नहीं","आप उठो और यहाँ पर आओ।"]],[5102,["बिल्कुल, मैं आपसे कहतीं हूँ।"]],[5116,["आएगा, आएगा। हाँ बेटे, अब देखो। तुम","दूसरों को मत सोचो. अपने को सोचो।"]],[5129,["कहो, \"माँ मेरे सर में आइए।\" तुम्हारे सर में","सारे ग्रन्थ भरे हुए हैं - तुम नहीं हो।"]],[5133,["साधक: नहीं, ऐसी कोई बात नहीं है।","श्री माताजी : नहीं पर मैं जानतीं हूँ ना।","मेरी बात मैं बता रहीं हूँ। हाँ।"]],[5137,["कहो, \"माँ, मेरे आप सर में आइए।\"","कुछ आ रहा हाथ में ठंडक? नहीं?"]],[5147,["हेलो दानिया, कृपया इन्हें आत्मसाक्षात्कार दीजिए।"]],[5155,["अच्छा वो हाथ अब करो। इस हाथ को करो।","सब को माफ़ करो, माफ़ करो।"]],[5166,["क्या हाल है तुम्हारा? कुछ नहीं हुआ ?","बनेगा, बनेगा। बन जाएगा थोड़ा।"]],[5172,["साधक: (अस्पष्ट)","वॉरेन: अब यह बंद हो गया। जब मैं यह","कर रहा हूँ तो यह (अस्पष्ट)"]],[5178,["वॉरेन: पहले इसे संतुलित होने दो। बस यह सोचो कि मैं कुछ नहीं कर रहा हूँ। माँ मैं कुछ नहीं करता।"]],[5190,["हो गया? क्या हो रहा है?","सहज योगी: जी माताजी लेफ्ट स्वाधिष्ठान लग रहा।","श्रीमाताजी: लेफ्ट स्वाधिष्ठान। अच्छा आओ।"]],[5200,["लो ये थोड़ा, ये ले ओ। इनके पीछे की","आज्ञा में लगा दो।"]],[5221,["क्या हो रहा है? कठिन काम है?"]],[5232,["इनको पार कराइए, इनको। आप बैठिए ज़रा","ज़मीन पर। ज़मीन पर आ जाइए, ज़मीन पर।"]],[5237,["हाँ, उठिए। विवेकानंद - बड़ा आसान काम नहीं।","ऐं?","सहज योगी: ज़ोर-ज़ोर की वाइब्रेशंस आ रहीं।"]],[5247,["श्री माताजी: क्या कह रहे?","सहज योगी: अब ज़ोर-ज़ोर की वाइब्रेशंस आ","रहीं हैं सर से।"]],[5250,["श्री माताजी: आ रहीं उनकी? बस ठीक है,","अब हो गए न ठीक?"]],[5253,["हाँ, अब इनको ज़रा देखो। ये महाबीर जी के वो हैं।","और इनको ये - ये पार नहीं हो रहे हैं।"]],[5259,["आप ये हाथ ऊपर करो, ये, ये। ये वाला हाथ","ऊपर करो, इधर आओ पास में। हम्म।"]],[5266,["और कहिए अब आप कि, \"मैंने सब को माफ़","कर दिया।\" कहो, पूरे मन से कहो।"]],[5270,["नहीं, मन में कहो लेकिन पूरे ह्रदय से कहो।","पूरे ह्रदय से कहना होगा, पूरे ह्रदय से कहो।"]],[5277,["हम्म! हो गया तुम्हारा? हो गया? नहीं हुआ? हाँ!","अब बोलो, आ रही? देखो, देखो ज़रा सा,","संवेदना देखो।"]],[5311,["आगे आओ। आपका हो गया बेटा? हो गए कि","नहीं? क्या हुआ? ज़रा उनको देखिए।"]],[5333,["हाँ!"]],[5337,["वॉरेन: माँ?","श्री माताजी: हँ","वॉरेन: क्या इन्हें आशीर्वाद मिलता है जब वह किसी को उपचार देता है?"]],[5341,["श्री माताजी: ऐं?","वारेन: क्या इन्हें आशीर्वाद मिलता है जब यह...."]],[5343,["श्री माताजी: भयंकर!","वारेन: नहीं आपको आशीर्वीद नहीं मिलता।"]],[5347,["श्री माताजी: नहीं तो अभी तक पार हो जाना था","अगर आप आशीर्वादित होते।"]],[5349,["वॉरेन: सिर्फ हमारा अहंकार सोचता है कि वह","आशीर्वादित है - बस इतना ही।"]],[5353,["श्री माताजी: हम्म, आप देखिए कि यह आप ही की","तरह के हैं। ये आपको बेहतर ढंग से समझते हैं -","थे।"]],[5361,["वारेन : एकदम वही पृष्ठभूमि।","श्री माताजी: वही पृष्ठभूमि।"]],[5365,["यही तो मैं कह रही थी, बिल्कुल सही।","वारेन: हम्म, यह सच है।"]],[5368,["श्री माताजी: यह उपचार करने के लिए","उचित व्यक्ति हैं। हाँ, अब!"]],[5370,["वॉरेन: हम्म (अस्पष्ट), वही शैली।","श्री माताजी: इन्होंने सभी प्रकार की चिकित्साएं","कीं थीं।"]],[5379,["वॉरेन: यह सब भूत विद्या के साथ खेल है।"]],[5383,["श्री माताजी: पर इनमें क्या है कि इनकी बुद्धि जो,","शुद्ध बुद्धि है बेटा। शुद्ध बुद्धि बहुत है, इसलिए","अहंकार को ये जमने नहीं देते।"]],[5391,["शुद्ध बुद्धि है। अगर कोई चीज़ समझ में आ गई,","चिपक जाते हैं। ये हममें नहीं।"]],[5396,["हम इधर-उधर चलते रहते हैं। बंदर-कूदी ज़्यादा","है। ये लोग जिस तरह से उठते हैं, आश्चर्य होता है।"]],[5411,["वारेन: कुंडलिनी बाकी सभी से बहुत ऊँची","होनी चाहिए, बहुत ऊँची - यह दिव्य ऊर्जा है।"]],[5417,["साधक: इसीलिए मैं यहाँ पर हूँ","वॉरेन: बिल्कुल। बस संतुलन बना रहे हैं","ताकि आपको शीतल चैतन्य महसूस हो।"]],[5428,["श्री माताजी: आपको यह सोचना चाहिए कि","मैं भाग्यशाली हूँ कि मैं यहाँ आया -","आपको ऐसा महसूस करना चाहिए।"]],[5433,["वॉरेन: ऐसा ही वो महसूस करते हैं।"]],[5435,["श्री माताजी: आपको ऐसा ही महसूस करना चाहिए,","कि आप भाग्यशाली हैं कि आप यहाँ हैं।"]],[5444,["इनकी विशुद्धि है, विशुद्धि नाभि ...."]],[5460,["हम्म! कैसा है (अस्पष्ट) - आज्ञा?","वह मुझे बता रही थी -"]],[5472,["उसका दाहिना हाथ मेरी ओर रखो और बायाँ","हाथ ऊपर रखो, वह ठीक हो जाएगी।"]],[5478,["मिसेस पड़गल कह रही थीं, 'मेरा गुस्सा अभी भी","है।' सहजयोगियों को आराम नहीं करना चाहिए,","काम करना चाहिए।"]],[5496,["यहाँ आओ, आओ। क्या है?"]],[5510,["इस छोटे लड़के पर काम करो,","हम्म, इन सज्जन पर।"]],[5517,["हाँ, हो रहा है? आ रहा है ना? इधर नीचे से","- अच्छा छोड़ो।"]],[5538,["उनके बाएं से दाएं करें, क्या आप आ सकते हैं?","आइए, इनको, यह सज्जन। इनको भी बाएं से दाएं।"]],[5574,["हाँ! जाना है। चलना है। नहीं बना?","साधक: यहाँ कम है।","श्री माताजी: चल रहा है।"]],[5600,["वह कैसे हैं?","सहज योगी: थोड़ा आ रहा है, माँ।"]],[5603,["श्री माताजी: ऐं?","साधक: थोड़ा सा आ रहा है माँ।","श्री माताजी: ठीक है।"]],[5605,["जितना हो सके उन्हें बाएँ से दाएँ करें।","इन सज्जन का क्या हुआ? उसे उठाओ।"]],[5613,["हम्म, नहीं आ रहा? गले में क्या पहने हो?","साधक: कंठी है (अस्पष्ट)।"]],[5621,["श्री माताजी: उतार लो ज़रा। एक मिनट, उतार","सकते हो? उतार लो, एक मिनट, अगर","उतार सको तो।"]],[5629,["विशुद्धि इसीलिए हो सकती है।","अंगूठी तो नहीं है हाथ में?"]],[5636,["साधक: अंगूठी खोल दी।","श्रीमाताजी: अच्छा घडी, घडी भी निकाल दो।"]],[5639,["उसको इधर पे नहीं, इधर नीचे रख लो, नीचे रख","लो। नीचे, सामने। इधर-उधर चित्त नहीं करना,","इधर ही देखो।"]],[5647,["अब ठीक है ना? मामला चल पड़ा, चलो बस।","अब आगे बढ़ना है बस। आज शाम को","आओ, और बढ़ेगा।"]],[5655,["दिनों दिन बढ़ते जाता है। तुम ठीक हो ना बेटा?","तुम्हारे लिए पूछ रहे हैं, तुम्हारे लिए।"]],[5661,["तुमको ही देख रहे, तुमको ही। ठीक हो ना?","नहीं हो रहा?"]],[5666,["तुम पूरा ले लो....डेविड, वह कैसा है? काफी कुछ।","हाँ, शाम को आओ - चलो।"]],[5676,["फिर, इस लड़के को देखो... वह बहुत अच्छा हो","सकता है, इसको पार कराओ। उसके बगल में,","पीछे में ... हम्म"]],[5686,["क्या हाल है? कुछ नहीं। कैसे हैं वो?"]],[5703,["क्या हुआ बेटा? तुम्हारा क्या हाल है? ठीक है?"]],[5710,["ऐं? आ गई ? तुम्हारे गुरु कौन हैं?","गुरुनानक? अच्छा ऐसे हाथ करो।"]],[5723,["कहो, \"माँ, आप साक्षात् गुरुनानक हो क्या,\"","पूछो। आँख खोल के पूछो भाई। हाँ, पूछो।","इधर देखो मेरी ओर।"]],[5742,["आई ठंडक?","साधक: (अस्पष्ट)।","श्री माताजी: हाँ (अस्पष्ट)। शुरुआत हो गई ना?"]],[5749,["हाँ, अब कहो, \"हो, आप माँ श्री गुरुनानक हो,\"","तो ज़बरदस्त जमेगा। हाँ!"]],[5756,["आपको हमेशा गुरु का नाम पूछना चाहिए।","श्री गुरुनानक उनके गुरु हैं। फिर क्या है?"]],[5762,["ऐसे सद्गुरु, सद्गुरु - तो इन्हें आत्मसाक्षात्कार","देना बहुत आसान है - होना चाहिए। हाँ!"]],[5766,["आया? देखो? आया ना? चलने दो, चलने दो।","आपके? आपका तो चल पड़ा है। वो तो","शकल पे दिखाई दे रहा है।"]],[5779,["आपका बेटे? नहीं बना अभी कुछ?"]],[5784,["उन्हें आत्मसाक्षात्कार दीजिए, आइए। इनको","दीजिए। नहीं हो रहा? कुछ भी काम नहीं","कर रहा है?"]],[5790,["कमाल है? हाँ, ये रहा। कुमकुम कहाँ है?","श्रीमती परदह? वो ले गईं? अच्छा बैठो, चलो।"]],[5802,["किसको मानते हो?","साधक: वो सभी मानता हूँ मैं, ख़ास तौर से","कृष्ण जी को।"]],[5807,["श्री माताजी: ख़ास तौर से। पूछो, \"माँ, आप","साक्षात् श्री कृष्ण हो,\" पूछो। हम्म, पूछो।"]],[5816,["इनकी कुण्डलिनी उठाओ, उठाओ। हाँ, ऊपर बाँध","दो। हाँ, अब उठाओ। ऊपर बाँध दो, ऊपर बाँध","दो, ऊपर बाँध दो।"]],[5841,["आया कुछ? हाथ की तरफ नज़र करो। शिव को","भी मानना है - सिर्फ कृष्ण को मानने से नहीं","होता है। शिव हैं।"]],[5859,["कौन सा मन्त्र बोलते हो?","साधक: (अस्पष्ट)।","श्री माताजी: बोलो, स्तुति बोलो।"]],[5875,["साधक: उनकी स्तुति पता है मन्त्र नहीं।","श्री माताजी: अच्छा कौन सी स्तुति करते हो?"]],[5879,["साधक: अस्पष्ट स्तुति।","श्री माताजी: आँख खोल के, आँख खोल के लो।"]],[5925,["श्री माताजी: आया ना? आ रही ठंडक?","आ रही कि नहीं?"]],[5935,["शुरआत हो गई। उंगलियाँ चमक गईं, देखो।","आ रही? ज़रा इनके सर पर देखो।"]],[5952,["उम्म, सर में, अभी तक नहीं? अभी तक नहीं"]],[5958,["कौन सी तरफ? ज़्यादा नहीं? गर्म? गुरु है?","कोई गुरु है?"]],[5975,["साधक: गुरु तो ...","श्री माताजी: कौन?","साधक: 'ब्रह्म सम्बन्ध' हम लेते हैं ..."]],[5983,["श्री माताजी: अरे भैया, काहे को ब्रह्म सम्बन्ध","लेते हो?"]],[5986,["साधक: बचपन में लिया था - गुरु का पूरा","याद भी नहीं है - अहमदाबाद के हैं।"]],[5990,["श्री माताजी: वो तो सब अहमदाबादी ऐसे ही होते हैं,","बेकार के लोग - ब्रह्म सम्बन्ध।"]],[5994,["बोलो, \"माँ, हमारा ब्रह्म सम्बन्ध करिए,\"","बोलो, चलो अभी बोलो।"]],[5999,["साधक: माँ हमारा ब्रह्म सम्बन्ध करिए।","श्री माताजी: 'माँ, कृपया हमारा ब्रह्म सम्बन्ध करिए।'"]],[6003,["साधक: माँ कृपया हमारा ब्रह्म सम्बन्ध करिए।","श्री माताजी: फिर से।"]],[6006,["साधक: माँ कृपया हमारा ब्रह्म सम्बन्ध करिए।","श्री माताजी: फिर से।"]],[6009,["साधक: माँ कृपया हमारा ब्रह्म सम्बन्ध करिए।","श्री माताजी: कुण्डलिनी।"]],[6012,["चढ़ पड़ी कुण्डलिनी इसी बात पे - हाँ!"]],[6016,["अब बोलो - ब्रह्म सम्बन्ध करने को आये,","पैसे खाऊ लोग।"]],[6021,["कुछ पवित्रता भी होनी चाहिए, कि बैठे ब्रह्म सम्बन्ध","करने और लड़कियों को खराब किया इन सब ने,","दुष्टों ने मिल कर के।"]],[6027,["वो रणछोरदास जी के मंदिर में ना? हम्म, ठीक","है। अब हाथ में आ रहा है? सर पे आ गया तुम्हारे।"]],[6037,["देखो अब चलो। हाथ भी ठन्डे हो गए कि नहीं,","हुए, लगा के देखो मुँह में। हो गए ठन्डे? रखो।"]],[6047,["ठीक है - एकादशा। वारेन, इनके एकादशा है।","बेहतर होगा कि आप इनके एकादश का","ध्यान रखें।"]],[6054,["उनको मिल गया?","सहज योगी: (अस्पष्ट) कल दोपहर को।"]],[6063,["वैष्णवों को तो चाहिए कि सबसे पहले प्राप्त हो।","साधक: आपकी कृपा हो जाये, माँ कि कृपा","हो जाये।"]],[6072,["श्री माताजी: वो नाभि पे बैठा है ना। हाँ देखिए,","ज़रा एक नजर डालें। इसे बाँध दो, ऊपर बाँध दो।"]],[6095,["ठीक, शुरू हो गया। देखो तुम, देखो।","महसूस करो, आँख बंद करो।"]],[6109,["हंसा? ये ठीक हैं, इनको प्राप्त हो गया है।","हो गया, शुरुआत हो गई है।"]],[6118,["इन्हें 'अल्लाह हो अकबर' सोलह बार कहने दो","- इनके हाथ काम करना शुरू कर देंगे।"]],[6122,["विराट हैं, विराट माने अकबर। और क्या, मोहम्मद","साहब ने कोई और की स्तुति थोड़े ही करी थी।"]],[6129,["श्री कृष्ण की ही स्तुति करी थी। वो तो हम लोग","समझते नहीं हैं और मुसलमान तो ऐसे ही गधे हैं।"]],[6137,["महा गधे लोग हैं। गधे पे ही बैठते थे, अभी गधे पे","ही बैठे हुए हैं। हाँ! और उनके साथ हम","भी गधे हो रहे हैं।"]],[6147,["क्योंकि जब गधों से कॉम्पीटीशन करोगे","तो आप भी गधे हो जाओगे।"]],[6151,["घोड़ों से कॉम्पीटीशन करो तो घोड़े हो जाओ।"]],[6154,["ज़रा इन महाशय को देखो। ऐसे हाथ करो बेटा।","ऐसे बैठो - तुम तो हाथ ऐसे बाँध के बैठे हो।"]],[6163,["आँख खोलो। इधर आप देखो उसको काहे, दूसरे","को काहे देख रहे हो? हम्म, अब ठीक है।","थोड़ा शुरुआत हो गई है।"]],[6175,["हमारे हिसाब से ब्रह्मसम्बन्ध हो गया है लेकिन","अभी आपके हाथ नहीं ठीक हैं।"]],[6180,["वो आपको बताएँगे - इनको 'अल्लाह हो अकबर'","करने को कहिए - इनका हो गया है।"]],[6187,["जागृति हो गई है। श्री राम और हनुमान जी का","नाम लो।"]],[6202,["क्या नाम तुम्हारा बेटा? तुम्हारा नाम तो बताओ?","ये शर्मा रहे हैं। आप बताइये आपका क्या नाम है?"]],[6213,["ये पार हैं, ये पैदा पार हैं। हम्म, क्या नाम?","अरे भई, बताओ, नाम बताओ - शर्मा रहे हो।"]],[6223,["इधर देखो। नाम तो बताना चाहिए","- जाने दीजिए शर्मा रहे हैं।"]],[6231,["इनकी नाक में भी थोड़ा घी डालें - इन्हें परेशानी है","- वही - आप ज़रा घी डलवा लो नाक में।"]],[6238,["जाओ वहाँ - घी है? तो थोड़ी सी रुई ले आएं।","उन्हें बुलाएँ - मुझे जाना है।"]],[6252,["आपको एक बजे जाना है, इसलिए आपको","12:30 बजे जाना होगा।"]],[6255,["श्री माताजी: उन्होंने कहा एक बजे, एक बजे","के बाद आना।","वॉरेन: योगी ने कहा कि वो बुलाएंगे और हमें (अस्पष्ट)?"]],[6261,["श्री माताजी योगी से: योगी, उन्होंने मुझे एक के बाद","आने को कहा था?","वॉरेन: उन्होंने कहा?"]],[6266,["श्री माताजी: हाँ","वॉरेन: आपने कहा था कि केवल तभी जब बुलाया जाए"]],[6269,["श्री माताजी: नहीं, नहीं, कैसे? आँ, किसने कहा?"]],[6272,["श्री माताजी: नहीं, उन्होंने निश्चित रूप से कहा","कि आपको एक बजे के बाद आना होगा।"]],[6276,["वारेन: ठीक है।","श्री माताजी: कॉल का कोई सवाल ही नहीं है।"]],[6280,["हम आपका इंतजार कर रहे हैं और मुझे","भी जाना होगा।"]],[6282,["वॉरेन: आप भी आ रहे हैं?","श्री माताजी: मैं वहाँ नहीं आ रही हूँ।"]],[6289,["हाँ, ज़रा डलवा लो, हो जायेगा। शुरू हो गया है,","सर में आ गया है। वो आ रहीं हैं।","आप देख लीजिए।"]],[6299,["[मराठी] जाओ इधर बैठो, वो डाल रहीं।"]],[6310,["वह कैसे हैं? उन्हें यह कहने के लिए कहें","कि \"माँ मेरे सिर में आइए।\""]],[6315,["हाँ क्या हो गया इनके?","सहज योगी: वह चैतन्य को बहुत अच्छी तरह","से सोख रहे हैं।"]],[6331,["इनका, तुम्हारा क्या हुआ? कुछ तो भला हो रहा है।"]],[6335,["बैठे रहो, बैठे रहो। सूर्य के सामने नहीं,","इधर बैठो नहीं तो बहुत - इधर से बैठो।"]],[6341,["एक तस्वीर ले आयें।"]],[6373,["नहीं, उन्हें कुछ महसूस नहीं हुआ? नहीं?"]],[6380,["विशुद्धि है - उनसे सोलह बार 'अल्लाह हो अकबर'","कहने को कहें सर ऊपर कर के।"]],[6401,["[मराठी]"]],[6408,["[मराठी]"]],[6419,["नहीं, सहज आसन, सहज आसन में ।"]],[6429,["नहीं ये वाला - हम्म बेहतर है।"]],[6444,["गरम है, अरे बाप रे बाप, एकदम तपा हुआ।","सिर्फ ऐसे कहना, 'माँ, मेरे सर में आइए।' बस, हाँ!","कृपया"]],[6457,["वॉरेन: श्रीमाताजी, क्या मुझे अकेले जाना चाहिए या","श्रीमाताजी: मैं श्रीमती ... के साथ जा रहीं हूँ","वॉरेन: नहीं, नहीं, मेरा मतलब है"]],[6462,["श्रीमाताजी: नहीं, नहीं, आप उन्हें अपने साथ ले जाएँ","और किसी राजस्थली साथी को","वॉरेन: अच्छा है, अच्छा है।"]],[6469,["श्री माताजी: इनको ले जाओ - क्या हुआ,","पार हुए कि नहीं?"]],[6474,["सहज योगी: थोड़ी आ रही है मेरे लेकिन","इनका क्या पकड़ रखा है।","श्री माताजी: क्या, भवसागर?"]],[6479,["सहज योगी: नाभि, भवसागर। (अस्पष्ट) गुरु जी","का कर रहे हैं ये सब।"]],[6483,["श्री माताजी: क्या कर रहे हैं ये कुण्डलिनी","का काम?"]],[6485,["सहज योगी: अपने चक्रों को साफ़-आफ करने","का काम।","श्री माताजी: कैसे?"]],[6488,["सहज योगी: मैंने इनको मना किया वो मत करिए।","श्री माताजी: पहले से है?"]],[6490,["सहज योगी: किसी ने बता दिया इन्हें पहले से ही।","श्री माताजी: किसने बताया था?"]],[6494,["सहज योगी: नाम भी बता देना उनका","- क्या नाम था उनका?","साधक: (अस्पष्ट)"]],[6500,["श्री माताजी: ऐं?","साधक: बाबा मार्ग कहते थे उनसे।"]],[6505,["श्री माताजी: सारा तो एकादश पकड़ा है।","सहज योगी: सब पकड़ा हुआ है इनका।"]],[6508,["श्री माताजी: ओह, ओह, ओह, ओह। क्या तमाशा","करते हैं! उतारिए इनकी, उतारिए पहले"]],[6515,["सहज योगी: इनको समझा दिया मैंने।","श्री माताजी: हम्म। लेफ्ट एंड राइट","सिम्पैथेटिक पहले उतारिए।"]],[6518,["इड़ा, पिंगला को उतार के, पूरी तरह से जब उतर","जाएगी, तब कुण्डलिनी की सफाई होएगी"]],[6523,["नहीं तो नहीं। इड़ा पिंगला दोनों चढ़ीं हैं,","आप ठीक करिए।"]],[6527,["बेटा एकादश पे है अभी। पूछो उनसे एकादश","का मन्त्र पूछो।"]],[6531,["ऐं?","साधक: (अस्पष्ट)","श्री माताजी: बेटा ये क्या करते हो?"]],[6536,["साधक: बात ये कि जब तक वो कुछ","पराकर्म दिखा दो तो छूट जाती है।"]],[6542,["श्री माताजी: उन्होंने दिखाया था क्या तुमको?","साधक: आप दिखा दो। (अस्पष्ट)"]],[6546,["श्री माताजी: बर्दाश्त नहीं कर पाओगे इसलिए।","बर्दाश्त कर सको तो दिखा दें।"]],[6550,["साधक: भगवान के आशीष से फिर दूसरा शरीर","मिल जायेगा लेकिन आप जानते हो न। (अस्पष्ट)"]],[6558,["श्री माताजी: रहन दो उनको ज़िद्दी आदमी हैं।","छोड़ो, उन्हीं के पास जाने दो, उन्हीं को","ठीक करने दो इन्हें।"]],[6566,["चलो, चलो, अच्छा जा रहे। खुश रहो!","सहज योगी: माताजी हम लिखेंगे तो आपसे","(अस्पष्ट) जानकर (अस्पष्ट)"]],[6574,["श्री माताजी: हाँ, आपको पहले जाना होगा और ...","सहज योगी: आपका नाम (अस्पष्ट) रखा बच्चों से।"]],[6578,["श्री माताजी: ऐं, क्या रखे हो?","सहज योगी: निर्मल है।"]],[6581,["श्री माताजी: अरे, फिर तो ऐसे ही बनो और","(अस्पष्ट)","सहज योगी: रहने वाले कन्नौज के हैं।"]],[6585,["श्री माताजी: कन्नौज के हो? अरे वाह रे वाह!","कन्नौज में कुछ काम करो, कन्नौज तो (अस्पष्ट)"]],[6595,["क्या हुआ? कैसे हैं वह? बेटा तुम्हारा हो क्यों","नहीं रहा है? हो क्यों नहीं रहा है?"]],[6603,["कहो, 'माँ, मेरे सर में आओ।' बोलो। इधर देखो","मेरी ओर। और उनका क्या?"]],[6613,["नहीं हुआ? चलो आज शाम को हो जायेगा।","चलो आ जायेगा। पेट का, गुरु का मामला है।"]],[6619,["थोड़ा पानी ले लो यहाँ से विब्रेटेड (चैतन्यित)।","आपके पास थोड़ी चीनी है इन लोगों के लिए?"]],[6623,["जितने गुरु वाले हैं उनको शुगर दे देते हैं।","शुगर मँगा लो।"]],[6627,["थोड़ी शुगर आज खा लो उससे गुरु","तत्व साफ़ हो जायेगा।"]],[6630,["ये तो आपका तो गुरु ऐसा बैठा है शकल से","दिखाई दे रहा है।"]],[6640,["क्या ऐसे गुरु को पकडे बैठे हो पागल जैसे।"]],[6643,["छोड़ो! हम्म। सारी कुण्डलिनी का मार्ग, सुषुम्ना","जो है आपकी, ऐसा हो रहा है।"]],[6667,["कैसे करें? गुरु को छोड़ो तो करें,","नहीं तो नहीं कर सकते।"]],[6670,["नहीं तो मगर पे बैठो, और कहो कि, 'मुझे नाव में","ले लो' - कैसे लें? मगर की पीठ तो छोड़ो पहले","- सीधा हिसाब।"]],[6677,["हमको कुछ लेना-देना नहीं, जाओ तुम अपने","गुरु के पास - उनसे ही करवाओ।"]],[6682,["अगर हमारे पास आना है तो - सद्गुरु हो तो","दूसरी बात। सद्गुरु तो है नहीं। हाँ, विशुद्धि।"]],[6688,["अभी देखो ये हैं गुरुनानक को मानतीं हैं,","उनका नाम लेती हैं, हाथ में आ गया।"]],[6692,["तुम्हारे अगर गुरु सद्गुरु होते तो हम उनको","ख़ुद मिलने जाते। समझे ना - सद्गुरु नहीं हैं।"]],[6698,["जो सच बात है सो कहनी पड़ेगी कि नहीं","- माँ क्या झूठ बोलेगी तुमसे?"]],[6705,["बेटे यही बात बता रहीं हूँ, कि सच बात ये है,","कि गुरु तत्व खराब हो जाता है, सारे चक्र,","ख़राब हो जाते हैं।"]],[6711,["सहज योगी: श्री माताजी आप आराम करिए।","श्री माताजी: नहीं, हमको जाना था। हाँ!"]],[6715,["क्या हुआ? हाँ, आ गया ना? देखो ये भी पार","हो गया। तुम्ही एक बच गए हो।"]],[6721,["साधक: कॉन्ट्रैक्शंस होता है कुछ","श्री माताजी: ऐं?"]],[6723,["साधक: कॉन्ट्रैक्शंस इस टाइप से होता है","श्री माताजी: ऐं?"]],[6728,["इनसे नाक में डलवा लो। अच्छा, सबको जिसको","गुरु की तकलीफ है, उसके लिए अभी चीनी","भिजवा देतीं हूँ।"]],[6744,["सबको थोड़ी-थोड़ी चीनी दे दो, अपनी चीनी","मिला के, चम्मच से फिर लेना, हाथ मत लगाना।"]],[6754,["सहज योगी: अब जिस जिसको कुछ गुरु का","प्रॉब्लम है वो मेहरबानी करके बैठे रहें।"]],[6758,["अभी चीनी आती है थोड़ा-थोड़ा ले जाइए अपनी","चीनी दान के बीच में उसको मिला दीजिये"]],[6764,["क्योंकि थोड़ी सी वाईब्रेटेड चीनी भी जो है अगर","आप अपनी चीनी दान में मिला देंगे, तो वो","बड़ा अच्छा काम करती है।"]],[6771,["और उसमें फिर कोशिश यही करें कि जब थोड़ा","ख़तम होने लगे तो उसमें और चीनी डाल दें,","तो वो वाईब्रेटेड ही रहेगी।"]],[6778,["ये ज़रूरी नहीं कि हर टाइम आप आ के चीनी","लें क्योंकि श्री माताजी तो कभी इधर होतीं,","कहीं वहाँ।"]],[6783,["थोड़ी सी चीनी आप अपने पूरे उसमें डाल के","रखिए और ख़तम होने से पहले"]],[6788,["उसी में फिर और मिला लीजिए, तो उससे","आपका सारा काम चल जायेगा।"]],[6792,["अब दो आपसे प्रार्थना हैं। एक तो भाई यहाँ पर","एक घूम रहे हैं और आपके नाम और पता","लेने के लिए"]],[6799,["ताकि आप तो संपर्क यहाँ रखेंगे, हमारी कोशिश","ये है कि हम भी आपके साथ संपर्क रख सकें।"]],[6807,["तो मेहरबानी करके अपना नाम और पता लिख","दीजिये, साफ़ तौर से लिखिए जिससे कि","आसानी हो जाए।"]],[6813,["दूसरा ये कि आपसे विनती है कि आज शाम","को आप प्रोग्राम पे आइये।"]],[6819,["जो भी आपके मित्र हैं जो खोज रहे हैं उनको","साथ ले आइए। ये तो भई काम ऐसा है"]],[6826,["जहाँ सिर्फ, ये कोई हमें लाभ नहीं होना, आपको","लाभ नहीं होना - हम सब का लाभ है इसमें।"]],[6834,["मैं आपको एक बात बता दूँ कि अगर हम आपसे","इस वक्त बैठ के बात कर रहे हैं,"]],[6838,["तो सिर्फ आपके फ़ायदे के लिए नहीं कर रहे,","हमारा भी इसमें लाभ है।"]],[6842,["क्योंकि ये जितनी उन्नति इक्कट्ठेपन में है,","वो अकेले-अकेले नहीं मिलती।"]],[6848,["तो आप देखेंगे जैसे-जैसे आप सहज योग में आप","आएंगे और स्थापित होंगे, आपको एक ऐसा","आनंद प्राप्त होगा"]],[6856,["कि जब एक के बजाये दस सहज योगी बैठते हैं,","तो क्या आनंद होता है - इसका तो अनुभव","ही हो सकता है, बताया नहीं जा सकता।"]],[6864,["और ये मैं उसमें से पहला आदमी था, जो सोचा","करता था कि, \"अरे, मैं घर में अपनी","पूजा भी कर लेता हूँ,\""]],[6870,["फुट-सोक भी कर लेता हूँ, और माँ की फोटो के","सामने मैं अपनी प्रार्थना भी कर लेता हूँ, मैं ध्यान","भी कर लेता हूँ,\""]],[6876,["\"तो क्या ज़रुरत है और किसी के साथ बैठने की।\"","पर जिस दिन पहली दफा मैं आश्रम में गया","- आश्रम वो जहाँ पर ..."]]]);
